tripCashCards=function(){const trip=state.trip.trip,records=[...state.trip.passengers,...state.trip.baggage],holderIds=records.filter(record=>record.cashHolderUserId&&!record.cashHandedOverAt).map(record=>record.cashHolderUserId),allStaff=[...new Set([trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId,...holderIds].filter(Boolean))],staffIds=state.user.role==='sales_manager'?[state.user.id]:allStaff;return`<div class="cash-custody">${staffIds.map(id=>{const held=records.filter(record=>record.cashHolderUserId===id&&!record.cashHandedOverAt),dkk=held.filter(record=>(record.paymentCurrency||'DKK')==='DKK').reduce((sum,record)=>sum+Number(record.cashAmount||0),0),eur=held.filter(record=>record.paymentCurrency==='EUR').reduce((sum,record)=>sum+Number(record.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b><small>${held.length} betalinger</small></div>`}).join('')}</div>`};

