// Mobile-first check-in cards. Secondary actions stay close, but out of the way.
checkinCard=function(p){
  const paymentClass=p.paymentStatus==='free'?'free':p.paymentStatus==='cash'?'paid':'unpaid';
  const paymentTitle=p.paymentStatus==='free'?'Gratis billet':p.paymentStatus==='cash'?'Betalt':'Ikke betalt';
  const paymentValue=p.paymentStatus==='free'?(p.freeTicketReason||'Ingen betaling'):p.paymentStatus==='cash'?'Betaling registreret':'Betaling mangler';
  const attendance=p.checkedIn?'checked':p.attendanceStatus==='no_show'?'noshow':'pending';
  return `<article class="checkin-card ${p.checkedIn?'is-checked':''} ${p.attendanceStatus==='no_show'?'is-noshow':''}" data-checkin-card="${p.id}" data-checkin-state="${attendance}" data-payment-state="${p.paymentStatus}" data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber} ${stopName(p.pickupStopId)} ${stopName(p.destinationStopId)}`.toLowerCase())}">
    <div class="checkin-seat"><small>SÆDE NR.</small><strong>${p.seatNumber}</strong></div>
    <div class="checkin-person"><small class="checkin-name-label">NAVN</small><button class="checkin-name-trigger" data-passenger-actions="${p.id}"><span>${esc(p.name)}</span><small>Tryk for handlinger</small><i>›</i></button><div class="checkin-route-summary"><div class="checkin-pickup"><small>OPSAMLINGSSTED</small><strong>${esc(stopName(p.pickupStopId))}</strong></div><div class="checkin-destination"><small>DESTINATION</small><strong>${esc(stopName(p.destinationStopId))}</strong></div></div><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a>${p.pendingSync?'<em>Afventer synkronisering</em>':''}</div>
    <div class="checkin-payment ${paymentClass}"><small>${paymentTitle}</small><strong>${esc(paymentValue)}</strong></div>
    <div class="checkin-actions">
      ${p.paymentStatus==='unpaid'?`<button class="pay-button" data-pay-passenger="${p.id}">Betal billet</button>`:''}
      ${!p.checkedIn?`<button class="check-button" data-fast-check="${p.id}">✓ Check ind</button>`:'<span class="checked-label">✓ Checket ind</span>'}
      <a href="tel:${esc(p.phone)}" class="icon-action checkin-call" title="Ring" aria-label="Ring til ${esc(p.name)}">☎</a>
      <details class="checkin-more"><summary aria-label="Flere handlinger">•••</summary><div>
        ${!p.checkedIn&&p.attendanceStatus!=='no_show'?`<button data-no-show="${p.id}">Marker udeblevet</button>`:''}
        <button data-passenger-detail="${p.id}">Se alle detaljer</button>
      </div></details>
    </div>
  </article>`
};

// Combined search and one-touch filters make long passenger lists manageable.
const checkInModeBeforeMobileWorkspace=renderCheckInMode;
renderCheckInMode=function(){
  checkInModeBeforeMobileWorkspace();
  const search=$('#checkinSearch'),sections=$('.checkin-sections');
  if(!search||!sections)return;
  const cards=$$('[data-checkin-card]');
  const counts={
    all:cards.length,
    pending:cards.filter(card=>card.dataset.checkinState==='pending').length,
    unpaid:cards.filter(card=>card.dataset.paymentState==='unpaid').length,
    checked:cards.filter(card=>card.dataset.checkinState==='checked').length
  };
  if(!['all','pending','unpaid','checked'].includes(state.checkInListFilter))state.checkInListFilter='pending';
  const tools=document.createElement('div');
  tools.className='checkin-mobile-tools';
  tools.innerHTML=`<div class="checkin-filter-label"><strong>Vis passagerer</strong><span id="checkinVisibleCount"></span></div><div class="checkin-filter-chips" role="group" aria-label="Filtrer check-in-listen">
    <button data-checkin-filter="pending">Afventer <b>${counts.pending}</b></button>
    <button data-checkin-filter="unpaid">Ikke betalt <b>${counts.unpaid}</b></button>
    <button data-checkin-filter="checked">Checket ind <b>${counts.checked}</b></button>
    <button data-checkin-filter="all">Alle <b>${counts.all}</b></button>
  </div>`;
  search.closest('.checkin-search').insertAdjacentElement('afterend',tools);
  const applyFilters=()=>{
    const query=search.value.trim().toLowerCase();
    let visible=0;
    cards.forEach(card=>{
      const matchesText=!query||card.dataset.search.includes(query);
      const filter=state.checkInListFilter;
      const matchesFilter=filter==='all'||filter==='pending'&&card.dataset.checkinState==='pending'||filter==='unpaid'&&card.dataset.paymentState==='unpaid'||filter==='checked'&&card.dataset.checkinState==='checked';
      card.hidden=!(matchesText&&matchesFilter);
      if(!card.hidden)visible++;
    });
    $$('.checkin-group').forEach(group=>{
      const groupCards=[...group.querySelectorAll('[data-checkin-card]')],shown=groupCards.filter(card=>!card.hidden).length;
      group.hidden=shown===0;
      const badge=group.querySelector('header span');if(badge)badge.textContent=shown;
    });
    $$('#tabContent [data-checkin-filter]').forEach(button=>{const active=button.dataset.checkinFilter===state.checkInListFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});
    const result=$('#checkinVisibleCount');if(result)result.textContent=`${visible} vist`;
  };
  search.oninput=applyFilters;
  $$('#tabContent [data-checkin-filter]').forEach(button=>button.onclick=()=>{state.checkInListFilter=button.dataset.checkinFilter;applyFilters();sections.scrollIntoView({behavior:'smooth',block:'start'})});
  $$('#tabContent .checkin-more').forEach(menu=>menu.addEventListener('toggle',()=>{
    if(!menu.open){menu.classList.remove('open-up');return}
    $$('#tabContent .checkin-more').forEach(other=>{if(other!==menu)other.open=false});
    menu.classList.remove('open-up');
    if(window.matchMedia('(min-width:701px)').matches)requestAnimationFrame(()=>{
      const panel=menu.querySelector('div'),group=menu.closest('.checkin-group');
      if(!panel||!group)return;
      const panelRect=panel.getBoundingClientRect(),groupRect=group.getBoundingClientRect();
      menu.classList.toggle('open-up',panelRect.bottom>window.innerHeight-12||panelRect.bottom>groupRect.bottom-8);
    });
  }));
  applyFilters();
};

// Advanced per-trip cash flow: ticket cash, baggage cash, expenses and custody.
const reportsBeforeAdvancedTripCash=renderReports;
renderReports=async function(){
  await reportsBeforeAdvancedTripCash();
  if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{
    const report=await api('/api/reports'),control=$('.economy-control');
    if(!control)return;
    control.insertAdjacentHTML('afterend','<section class="advanced-trip-economy" id="advancedTripEconomy"></section>');
    const refresh=()=>renderAdvancedTripEconomy(report);
    ['#economyFrom','#economyTo','#economyTrip','#economyCurrency'].forEach(selector=>$(selector)?.addEventListener('change',refresh));
    $('#resetEconomy')?.addEventListener('click',()=>setTimeout(refresh));
    refresh();
  }catch(error){toast(error.message)}
};

function economyAmount(rows,path){
  return ['DKK','EUR'].reduce((totals,currency)=>{totals[currency]=rows.reduce((sum,row)=>{let value=row;for(const key of path.split('.'))value=value?.[key];return sum+Number(value?.[currency]||0)},0);return totals},{});
}
function economyValues(amounts,currency,strong=false){
  const currencies=currency==='all'?['DKK','EUR']:[currency];
  return currencies.map(code=>`<span class="currency-value ${code.toLowerCase()}">${strong?'<strong>':''}${money(amounts?.[code]||0,code)}${strong?'</strong>':''}</span>`).join('');
}
function cashStage(label,amounts,currency,kind,note){return`<div class="cash-stage ${kind}"><span>${label}</span>${economyValues(amounts,currency,true)}<small>${note}</small></div>`}
function renderAdvancedTripEconomy(report){
  const host=$('#advancedTripEconomy');if(!host)return;
  const rows=filteredTripResults(report),currency=$('#economyCurrency').value;
  const ticket=economyAmount(rows,'ticketRevenue'),baggage=economyAmount(rows,'baggageRevenue'),expenses=economyAmount(rows,'approvedExpenses'),net=economyAmount(rows,'net'),shop=economyAmount(rows,'cashFlow.shop'),handed=economyAmount(rows,'cashFlow.handedOver'),held=economyAmount(rows,'cashFlow.held');
  const totals={DKK:ticket.DKK+baggage.DKK,EUR:ticket.EUR+baggage.EUR};
  const discrepancy={DKK:totals.DKK-shop.DKK-handed.DKK-held.DKK,EUR:totals.EUR-shop.EUR-handed.EUR-held.EUR},hasDiscrepancy=Math.abs(discrepancy.DKK)>.001||Math.abs(discrepancy.EUR)>.001;
  const currencies=currency==='all'?['DKK','EUR']:[currency];
  const mix=currencies.map(code=>{const total=totals[code]||0,ticketPct=total?Math.round(ticket[code]/total*100):0,baggagePct=total?100-ticketPct:0;return`<div class="revenue-mix-row"><strong>${code}</strong><div class="revenue-mix-bar"><i style="width:${ticketPct}%"></i><b style="width:${baggagePct}%"></b></div><span>Billetter ${ticketPct}%</span><span>Bagage ${baggagePct}%</span></div>`}).join('');
  const holders=new Map();rows.flatMap(row=>row.cashFlow?.byHolder||[]).forEach(holder=>{const current=holders.get(holder.userName)||{name:holder.userName,payments:0,DKK:0,EUR:0};current.payments+=holder.payments;current.DKK+=holder.amounts.DKK;current.EUR+=holder.amounts.EUR;holders.set(holder.userName,current)});
  host.innerHTML=`<header class="advanced-economy-head"><div><small>AVANCERET TURANALYSE</small><h2>Hvor kommer pengene fra – og hvor står de?</h2><p>${rows.length===1?'Viser den valgte tur':`Samlet visning for ${rows.length} ture`}</p></div><span>${currency==='all'?'DKK og EUR':currency}</span></header>${hasDiscrepancy?`<div class="economy-discrepancy"><strong>Kontroladvarsel</strong><span>Registreret salg stemmer ikke med placeringen af kontanterne: ${economyValues(discrepancy,currency,true)}</span></div>`:''}
    <div class="advanced-kpis"><div class="ticket-kpi"><small>Kontanter fra billetter</small>${economyValues(ticket,currency,true)}<em>${rows.reduce((sum,row)=>sum+row.paidTickets,0)} betalte billetter</em></div><div class="baggage-kpi"><small>Kontanter fra bagage</small>${economyValues(baggage,currency,true)}<em>${rows.reduce((sum,row)=>sum+row.paidBaggage,0)} betalte forsendelser</em></div><div class="expense-kpi"><small>Godkendte udgifter</small>${economyValues(expenses,currency,true)}<em>${rows.reduce((sum,row)=>sum+(row.expenseCategories||[]).length,0)} udgiftskategorier</em></div><div class="net-kpi ${currencies.some(code=>net[code]<0)?'negative':'positive'}"><small>Nettoresultat</small>${economyValues(net,currency,true)}<em>Omsætning minus godkendte udgifter</em></div></div>
    <div class="advanced-economy-grid"><section class="cash-flow-panel"><h3>Kontanternes placering</h3><div class="cash-flow-line">${cashStage('Registreret i salgsbutikken',shop,currency,'shop','Allerede hos kontoret')}${cashStage('Afleveret og godkendt',handed,currency,'office','Afstemt fra personale')}${cashStage('Står stadig hos personale',held,currency,'held','Skal kontantafstemmes')}</div>${holders.size?`<div class="cash-holder-breakdown"><strong>Uafleveret per medarbejder</strong>${[...holders.values()].map(holder=>`<div><span>${esc(holder.name)}<small>${holder.payments} betalinger</small></span>${economyValues(holder,currency,true)}</div>`).join('')}</div>`:'<p class="all-settled">✓ Ingen uafleverede kontanter i den valgte visning</p>'}</section><section class="revenue-mix"><h3>Fordeling af kontantsalg</h3>${mix}<div class="mix-total"><span>Samlet kontantsalg</span>${economyValues(totals,currency,true)}</div></section></div>
    <section class="trip-economy-list"><header><h3>Detaljer per tur</h3><span>${rows.length} ture</span></header>${rows.length?rows.map((row,index)=>tripEconomyDetail(row,currency,rows.length===1||index===0)).join(''):'<div class="empty">Ingen ture matcher de valgte filtre</div>'}</section>`;
}
function tripEconomyDetail(row,currency,open){
  const currencies=currency==='all'?['DKK','EUR']:[currency],negative=currencies.some(code=>row.net[code]<0),settlementText=row.cashFlow.held.DKK||row.cashFlow.held.EUR?'Kontanter mangler afstemning':'Kontanter afstemt';
  const categories=(row.expenseCategories||[]).map(item=>`<div><span>${esc(item.category)}</span>${economyValues(item.approved,currency,true)}${(item.pending.DKK||item.pending.EUR)?`<small>Afventer: ${currencies.map(code=>money(item.pending[code],code)).join(' · ')}</small>`:''}</div>`).join('')||'<p>Ingen udgifter på turen</p>';
  return`<details class="trip-economy-detail" ${open?'open':''}><summary><div><strong>${esc(row.title)}</strong><small>${date(row.departureAt)} · ${esc(row.busName)}</small></div><span class="trip-cash-status ${row.cashFlow.held.DKK||row.cashFlow.held.EUR?'attention':'done'}">${settlementText}</span><div class="trip-net ${negative?'negative':'positive'}"><small>Netto</small>${economyValues(row.net,currency,true)}</div><b>⌄</b></summary><div class="trip-economy-body"><div class="trip-money-grid"><div><span>Billetter</span>${economyValues(row.ticketRevenue,currency,true)}<small>${row.paidTickets} betalt · ${row.freeTickets} gratis · ${row.unpaid} ubetalt</small></div><div><span>Bagage</span>${economyValues(row.baggageRevenue,currency,true)}<small>${row.paidBaggage} betalt · ${row.unpaidBaggage} ubetalt</small></div><div><span>Godkendte udgifter</span>${economyValues(row.approvedExpenses,currency,true)}</div><div class="${negative?'negative':'positive'}"><span>Nettoresultat</span>${economyValues(row.net,currency,true)}</div></div><div class="trip-cash-chain">${cashStage('Salgsbutik',row.cashFlow.shop,currency,'shop','Direkte hos kontoret')}${cashStage('Afleveret',row.cashFlow.handedOver,currency,'office',`${row.settlements.approved} godkendte afstemninger`)}${cashStage('Hos personale',row.cashFlow.held,currency,'held',`${row.settlements.pending} afstemninger afventer`)}</div><div class="expense-category-list"><h4>Udgifter efter kategori</h4>${categories}</div></div></details>`
}

exportEconomyCsv=function(rows){const header=['Tur','Dato','Bus','Passagerer','Kapacitet','Belægning %','Billetter DKK','Billetter EUR','Bagage DKK','Bagage EUR','Salgsbutik DKK','Salgsbutik EUR','Afleveret DKK','Afleveret EUR','Hos personale DKK','Hos personale EUR','Godkendte udgifter DKK','Godkendte udgifter EUR','Afventende udgifter DKK','Afventende udgifter EUR','Netto DKK','Netto EUR'],data=rows.map(r=>[r.title,r.departureAt,r.busName,r.passengers,r.seatCount,r.occupancy,r.ticketRevenue.DKK,r.ticketRevenue.EUR,r.baggageRevenue.DKK,r.baggageRevenue.EUR,r.cashFlow.shop.DKK,r.cashFlow.shop.EUR,r.cashFlow.handedOver.DKK,r.cashFlow.handedOver.EUR,r.cashFlow.held.DKK,r.cashFlow.held.EUR,r.approvedExpenses.DKK,r.approvedExpenses.EUR,r.pendingExpenses.DKK,r.pendingExpenses.EUR,r.net.DKK,r.net.EUR]),csv=[header,...data].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='avanceret-turoekonomi.csv';link.click();URL.revokeObjectURL(url)};

// A trip expense folder designed for quick mobile capture and office approval.
function expenseMethodLabel(method){return({company_card:'Firmakort',cash:'Kontanter',private:'Privat udlæg'})[method]||'Kontanter'}
function expenseStatusLabel(status){return status==='approved'?'Godkendt':status==='rejected'?'Afvist':'Afventer'}
function expenseCard(expense){
  const status=expense.status||'pending',method=expense.paymentMethod||'cash',missing=!expense.receiptFile,privatePending=method==='private'&&status==='approved'&&(expense.reimbursementStatus||'pending')!=='paid';
  return`<article class="expense-folder-card" data-expense-card data-expense-status="${status}" data-expense-receipt="${missing?'missing':'attached'}"><div class="expense-card-icon">${missing?'!':'▧'}</div><div class="expense-card-title"><small>${date(expense.expenseDate||expense.createdAt)}</small><h3>${esc(expense.category)}</h3><p>${esc(expense.description||'Ingen beskrivelse')}</p></div><div class="expense-card-amount"><strong>${money(expense.amount,expense.currency)}</strong><span class="expense-status ${status}">${expenseStatusLabel(status)}</span></div><div class="expense-card-meta"><span>${expenseMethodLabel(method)}</span><span>Betalt af <b>${esc(expense.paidByName||expense.createdByName||'Ukendt')}</b></span><span>Registreret af <b>${esc(expense.createdByName||'Ukendt')}</b></span>${method==='private'?`<span class="reimbursement ${expense.reimbursementStatus==='paid'?'paid':'pending'}">${expense.reimbursementStatus==='paid'?'✓ Tilbagebetalt':'Afventer tilbagebetaling'}</span>`:''}</div><div class="expense-receipt ${missing?'missing':''}">${missing?`<strong>Kvittering mangler</strong><label class="attach-receipt">Tilføj kvittering<input type="file" accept="image/*,application/pdf" capture="environment" data-attach-receipt="${expense.id}"></label>`:`<span>Kvittering vedhæftet</span><a href="/api/expenses/${expense.id}/receipt" target="_blank">Åbn bilag ↗</a>`}</div>${expense.reviewNote?`<div class="expense-review-note"><strong>Kommentar</strong><span>${esc(expense.reviewNote)}</span></div>`:''}<div class="expense-card-actions">${state.user.role==='admin'&&status==='pending'?`<button class="mini done" data-approve-expense="${expense.id}" ${missing?'disabled title="Kvittering mangler"':''}>Godkend</button><button class="mini danger" data-reject-expense="${expense.id}">Afvis</button>`:''}${state.user.role==='admin'&&privatePending?`<button class="mini reimburse" data-reimburse-expense="${expense.id}">Marker tilbagebetalt</button>`:''}</div></article>`
}
renderExpensesTab=function(){
  const expenses=state.trip.expenses||[],trip=state.trip.trip,statusTotals=status=>['DKK','EUR'].reduce((totals,currency)=>{totals[currency]=expenses.filter(item=>(item.status||'pending')===status&&item.currency===currency).reduce((sum,item)=>sum+Number(item.amount||0),0);return totals},{}),approved=statusTotals('approved'),pending=statusTotals('pending'),privatePending=expenses.filter(item=>(item.paymentMethod||'cash')==='private'&&(item.reimbursementStatus||'pending')!=='paid'&&(item.status||'pending')!=='rejected'),missing=expenses.filter(item=>!item.receiptFile).length;
  const payerOptions=state.user.role==='admin'?[state.user,...(state.drivers||[]).filter(driver=>[trip.primaryDriverId,trip.secondaryDriverId].includes(driver.id))]:[state.user];
  $('#tabContent').innerHTML=`<section class="expense-folder-hero"><div><small>DIGITAL UDGIFTSMAPPE</small><h2>${esc(trip.title)}</h2><p>${date(trip.departureAt)} · Alle udgifter gemmes direkte på denne tur</p></div><button class="primary" id="jumpExpenseForm">+ Tilføj udgift</button></section><div class="expense-folder-summary"><div><small>Godkendt</small>${economyValues(approved,'all',true)}</div><div><small>Afventer godkendelse</small>${economyValues(pending,'all',true)}</div><div><small>Private udlæg åbne</small><strong>${privatePending.length}</strong></div><div class="${missing?'attention':''}"><small>Mangler kvittering</small><strong>${missing}</strong></div></div><div class="expense-folder-filters"><button class="active" data-expense-filter="all">Alle <b>${expenses.length}</b></button><button data-expense-filter="pending">Afventer <b>${expenses.filter(item=>(item.status||'pending')==='pending').length}</b></button><button data-expense-filter="approved">Godkendt <b>${expenses.filter(item=>item.status==='approved').length}</b></button><button data-expense-filter="rejected">Afvist <b>${expenses.filter(item=>item.status==='rejected').length}</b></button><button data-expense-filter="missing">Mangler kvittering <b>${missing}</b></button></div><div class="expense-folder-layout"><section class="expense-card-list" id="expenseCardList">${expenses.length?expenses.map(expenseCard).join(''):'<div class="empty expense-empty">Ingen udgifter er registreret på turen</div>'}</section><aside class="expense-entry-panel" id="expenseEntryPanel"><header><span>＋</span><div><small>NY TURUDGIFT</small><h3>Registrer udgift</h3></div></header><form class="form" id="expenseForm"><label>Kategori<select name="category"><option>Brændstof</option><option>Vejafgift</option><option>Færge</option><option>Parkering</option><option>Reparation</option><option>Forplejning</option><option>Overnatning</option><option>Andet</option></select></label><label>Beløb<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" required></label><label>Valuta<select name="currency"><option value="DKK">DKK</option><option value="EUR">EUR</option></select></label><label>Betalingsmetode<select name="paymentMethod"><option value="company_card">Firmakort</option><option value="cash">Kontanter</option><option value="private">Privat udlæg</option></select></label><label class="wide">Betalt af<select name="paidByUserId">${payerOptions.map(person=>`<option value="${person.id}">${esc(person.name)}</option>`).join('')}</select></label><label class="wide receipt-capture"><span>Kvittering <small>kan tilføjes senere</small></span><input name="receipt" type="file" accept="image/*,application/pdf" capture="environment"><b>Tag billede eller vælg fil</b><em>PDF eller billede · maks. 5 MB</em></label><label class="wide">Beskrivelse<textarea name="description" placeholder="Hvad blev købt, og hvorfor?"></textarea></label><button class="primary wide">Gem udgift på turen</button></form></aside></div>`;
  $('#expenseForm').onsubmit=uploadExpense;$('#jumpExpenseForm').onclick=()=>$('#expenseEntryPanel').scrollIntoView({behavior:'smooth',block:'start'});
  $$('[data-expense-filter]').forEach(button=>button.onclick=()=>{$$('[data-expense-filter]').forEach(item=>item.classList.toggle('active',item===button));$$('[data-expense-card]').forEach(card=>card.hidden=!(button.dataset.expenseFilter==='all'||card.dataset.expenseStatus===button.dataset.expenseFilter||button.dataset.expenseFilter==='missing'&&card.dataset.expenseReceipt==='missing'))});
  $$('[data-approve-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.approveExpense),'approved'));$$('[data-reject-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.rejectExpense),'rejected'));$$('[data-reimburse-expense]').forEach(button=>button.onclick=()=>reimburseExpense(Number(button.dataset.reimburseExpense)));$$('[data-attach-receipt]').forEach(input=>input.onchange=()=>attachExpenseReceipt(Number(input.dataset.attachReceipt),input.files[0]));
};

uploadExpense=async function(event){event.preventDefault();const form=event.target,file=form.receipt.files[0];if(file&&file.size>5*1024*1024)return toast('Kvitteringen må højst fylde 5 MB');try{const payload={category:form.category.value,amount:form.amount.value,currency:form.currency.value,paymentMethod:form.paymentMethod.value,paidByUserId:form.paidByUserId.value,description:form.description.value};if(file)Object.assign(payload,{receiptName:file.name,receiptType:file.type,receiptData:await fileAsDataUrl(file)});const expense=await api(`/api/trips/${state.trip.trip.id}/expenses`,{method:'POST',body:JSON.stringify(payload)});state.trip.expenses.push(expense);toast(file?'Udgiften og kvitteringen er gemt':'Udgiften er gemt · kvittering mangler');renderTrip()}catch(error){toast(error.message)}};
async function attachExpenseReceipt(id,file){if(!file)return;if(file.size>5*1024*1024)return toast('Kvitteringen må højst fylde 5 MB');try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({receiptName:file.name,receiptType:file.type,receiptData:await fileAsDataUrl(file)})});Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast('Kvitteringen er tilføjet');renderTrip()}catch(error){toast(error.message)}}
reviewExpense=async function(id,status){let reviewNote='';if(status==='rejected'){const reason=prompt('Hvorfor afvises udgiften?');if(reason===null)return;reviewNote=reason}try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({status,reviewNote})});if(state.trip?.expenses?.some(item=>item.id===id)){Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');renderTrip()}else{toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');renderReports()}}catch(error){toast(error.message)}};
async function reimburseExpense(id){if(!confirm('Bekræft, at det private udlæg er tilbagebetalt.'))return;try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({reimbursementStatus:'paid'})});Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast('Udlægget er markeret som tilbagebetalt');renderTrip()}catch(error){toast(error.message)}}

const reportsBeforeMissingReceipts=renderReports;
renderReports=async function(){await reportsBeforeMissingReceipts();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports'),expensePanel=[...$$('.report-section')].find(panel=>panel.querySelector('h2')?.textContent==='Turudgifter og kvitteringer');if(expensePanel)[...expensePanel.querySelectorAll('tbody tr')].forEach((row,index)=>{if(report.expenses[index]?.receiptFile)return;row.cells[row.cells.length-1].innerHTML='<span class="missing-receipt-label">Kvittering mangler</span>'});const pending=report.expenses.filter(item=>(item.status||'pending')==='pending'),approvalPanel=$('.expense-approval-panel');if(approvalPanel)[...approvalPanel.querySelectorAll('tbody tr')].forEach((row,index)=>{if(pending[index]?.receiptFile)return;row.cells[3].innerHTML='<span class="missing-receipt-label">Mangler</span>';const approve=row.querySelector('[data-approve-expense]');if(approve){approve.disabled=true;approve.title='Kvittering skal tilføjes fra turens udgiftsmappe'}})}catch(error){toast(error.message)}};

// Operations calendar with today, week and month views.
const newTripBeforeDuration=$('#newTrip').onclick;
$('#newTrip').onclick=()=>{newTripBeforeDuration();const form=$('#createTrip');if(!form||form.durationMinutes)return;form.departureAt.closest('label').insertAdjacentHTML('afterend','<label>Forventet varighed<select name="durationMinutes"><option value="240">4 timer</option><option value="360">6 timer</option><option value="480" selected>8 timer</option><option value="600">10 timer</option><option value="720">12 timer</option><option value="1440">24 timer</option></select></label>')};

function calendarDayKey(value){return copenhagenDayKey(value)}
function calendarAnchor(){return new Date(`${state.calendarDate||calendarDayKey(new Date())}T12:00:00`)}
function calendarMonday(value){const day=new Date(value),offset=(day.getDay()+6)%7;day.setDate(day.getDate()-offset);day.setHours(0,0,0,0);return day}
function calendarStatus(trip){const now=Date.now(),start=new Date(trip.departureAt).getTime(),end=start+Number(trip.durationMinutes||480)*60000;if(trip.status==='cancelled')return'cancelled';if(trip.status==='completed'||now>end)return'completed';if(now>=start&&now<=end)return'underway';if(start-now<=2*60*60*1000&&start>now)return'checkin';return'planned'}
function calendarStatusLabel(status){return({planned:'Planlagt',checkin:'Check-in åbner',underway:'Undervejs',completed:'Afsluttet',cancelled:'Annulleret'})[status]||'Planlagt'}
function calendarConflicts(trips){const conflicts=new Map(trips.map(trip=>[trip.id,new Set()]));for(let i=0;i<trips.length;i++)for(let j=i+1;j<trips.length;j++){const a=trips[i],b=trips[j],aStart=new Date(a.departureAt).getTime(),aEnd=aStart+Number(a.durationMinutes||480)*60000,bStart=new Date(b.departureAt).getTime(),bEnd=bStart+Number(b.durationMinutes||480)*60000;if(aStart>=bEnd||bStart>=aEnd)continue;const labels=[];if(a.busId&&a.busId===b.busId)labels.push(`Bus: ${a.bus?.name||'samme bus'}`);const aDrivers=[a.primaryDriverId,a.secondaryDriverId].filter(Boolean),bDrivers=[b.primaryDriverId,b.secondaryDriverId].filter(Boolean),driver=aDrivers.find(id=>bDrivers.includes(id));if(driver)labels.push(`Chauffør: ${state.drivers?.find(item=>item.id===driver)?.name||a.primaryDriver||a.secondaryDriver||'samme chauffør'}`);labels.forEach(label=>{conflicts.get(a.id).add(label);conflicts.get(b.id).add(label)})}return conflicts}
function filteredCalendarTrips(){const filter=state.calendarFilters||{},query=(filter.query||'').toLowerCase();return state.trips.filter(trip=>(!query||`${trip.title} ${trip.origin?.name||''} ${trip.destination?.name||''} ${trip.primaryDriver||''} ${trip.bus?.name||''}`.toLowerCase().includes(query))&&(!filter.busId||trip.busId===Number(filter.busId))&&(!filter.driverId||[trip.primaryDriverId,trip.secondaryDriverId].includes(Number(filter.driverId)))&&(!filter.status||calendarStatus(trip)===filter.status)).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt))}
function calendarTripCard(trip,conflicts,compact=false){const status=calendarStatus(trip),capacity=trip.seatCount||trip.bus?.seatCount||0,occupancy=capacity?Math.round(trip.counts.passengers/capacity*100):0,issues=conflicts.get(trip.id)?.size||0,end=new Date(new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000);return`<button class="ops-trip-card status-${status} ${compact?'compact':''}" data-calendar-trip="${trip.id}"><span class="ops-trip-time"><b>${copenhagenTime(trip.departureAt)}</b><small>til ${copenhagenTime(end)}</small></span><span class="ops-trip-main"><i>${calendarStatusLabel(status)}</i><strong>${esc(trip.title)}</strong><small>${esc(trip.origin?.name||'–')} → ${esc(trip.destination?.name||'–')}</small></span>${compact?'':`<span class="ops-trip-staff"><small>${esc(trip.bus?.name||'Ingen bus')}</small><b>${esc(trip.primaryDriver||'Ingen chauffør')}</b></span><span class="ops-trip-progress"><b>${trip.counts.checkedIn}/${trip.counts.passengers}</b><small>checket ind</small><i><em style="width:${trip.counts.passengers?Math.round(trip.counts.checkedIn/trip.counts.passengers*100):0}%"></em></i></span><span class="ops-trip-occupancy"><b>${trip.counts.passengers}/${capacity||'–'}</b><small>${occupancy}% belægning</small></span>`}${issues?`<span class="ops-conflict-badge" title="Ressourcekonflikt">! ${issues}</span>`:''}</button>`}
function calendarTodayView(trips,conflicts,anchor){const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(anchor));return`<div class="ops-day-heading"><span>${anchor.toLocaleDateString('da-DK',{weekday:'long'})}</span><strong>${anchor.toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'})}</strong></div><div class="ops-timeline">${dayTrips.length?dayTrips.map(trip=>`<div class="ops-timeline-row"><div><i></i></div>${calendarTripCard(trip,conflicts)}</div>`).join(''):'<div class="ops-calendar-empty"><strong>Ingen ture denne dag</strong><span>Vælg en anden dato eller opret en ny tur.</span></div>'}</div>`}
function calendarWeekView(trips,conflicts,anchor){const start=calendarMonday(anchor);return`<div class="ops-week">${Array.from({length:7},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(day));return`<section class="ops-week-day ${calendarDayKey(day)===calendarDayKey(new Date())?'today':''}"><header><span>${day.toLocaleDateString('da-DK',{weekday:'short'})}</span><strong>${day.getDate()}</strong><small>${dayTrips.length} ture</small></header><div>${dayTrips.map(trip=>calendarTripCard(trip,conflicts,true)).join('')||'<p>Ingen ture</p>'}</div></section>`}).join('')}</div>`}
function calendarMonthView(trips,conflicts,anchor){const first=new Date(anchor.getFullYear(),anchor.getMonth(),1),start=calendarMonday(first),weekdays=['Man','Tir','Ons','Tor','Fre','Lør','Søn'];return`<div class="ops-month-weekdays">${weekdays.map(day=>`<span>${day}</span>`).join('')}</div><div class="ops-month">${Array.from({length:42},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(day));return`<section class="ops-month-day ${dayTrips.length?'has-trips':''} ${day.getMonth()!==anchor.getMonth()?'muted':''} ${calendarDayKey(day)===calendarDayKey(new Date())?'today':''}"><header><strong>${day.getDate()}</strong><span>${dayTrips.length||''}</span></header><div>${dayTrips.slice(0,3).map(trip=>calendarTripCard(trip,conflicts,true)).join('')}${dayTrips.length>3?`<button class="more-trips" data-calendar-mode-day="${calendarDayKey(day)}">+ ${dayTrips.length-3} flere</button>`:''}</div></section>`}).join('')}</div>`}

renderCalendar=function(){state.trip=null;activate('calendar');setTitle('Turkalender','DRIFTSCENTER');state.calendarMode=state.calendarMode||'today';state.calendarDate=state.calendarDate||calendarDayKey(new Date());state.calendarFilters=state.calendarFilters||{};const anchor=calendarAnchor(),trips=filteredCalendarTrips(),activeTrips=state.trips.filter(trip=>!['completed','cancelled'].includes(calendarStatus(trip))),conflicts=calendarConflicts(activeTrips),conflictTrips=activeTrips.filter(trip=>conflicts.get(trip.id)?.size).length,missingStaff=activeTrips.filter(trip=>!trip.busId||!trip.primaryDriverId).length,missingReceipts=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.missingReceipts||0),0),unsettled=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.unsettledCash||0),0),unpaid=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.unpaid||0),0),buses=[...new Map(state.trips.filter(trip=>trip.busId).map(trip=>[trip.busId,trip.bus])).entries()],drivers=[...new Map(state.trips.flatMap(trip=>[[trip.primaryDriverId,trip.primaryDriver],[trip.secondaryDriverId,trip.secondaryDriver]]).filter(([id])=>id)).entries()];let title=anchor.toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'}),body=calendarTodayView(trips,conflicts,anchor);if(state.calendarMode==='week'){const start=calendarMonday(anchor),end=new Date(start);end.setDate(start.getDate()+6);title=`${start.toLocaleDateString('da-DK',{day:'numeric',month:'short'})} – ${end.toLocaleDateString('da-DK',{day:'numeric',month:'short',year:'numeric'})}`;body=calendarWeekView(trips,conflicts,anchor)}if(state.calendarMode==='month'){title=anchor.toLocaleDateString('da-DK',{month:'long',year:'numeric'});body=calendarMonthView(trips,conflicts,anchor)}$('#view').innerHTML=`<section class="ops-alert-strip"><div class="${conflictTrips?'danger':'ok'}"><b>${conflictTrips}</b><span>Ressourcekonflikter</span></div><div class="${missingStaff?'warning':'ok'}"><b>${missingStaff}</b><span>Mangler bemanding/bus</span></div><div class="${missingReceipts?'warning':'ok'}"><b>${missingReceipts}</b><span>Mangler kvittering</span></div><div class="${unsettled?'warning':'ok'}"><b>${unsettled}</b><span>Uafleverede betalinger</span></div><div class="${unpaid?'warning':'ok'}"><b>${unpaid}</b><span>Ubetalte salg</span></div></section><section class="ops-calendar-shell"><header class="ops-calendar-toolbar"><div class="ops-view-switch"><button data-calendar-mode="today" class="${state.calendarMode==='today'?'active':''}">I dag</button><button data-calendar-mode="week" class="${state.calendarMode==='week'?'active':''}">Uge</button><button data-calendar-mode="month" class="${state.calendarMode==='month'?'active':''}">Måned</button></div><div class="ops-date-nav"><button id="calendarPrevious" aria-label="Forrige">‹</button><strong>${title}</strong><button id="calendarNext" aria-label="Næste">›</button><button id="calendarToday">I dag</button></div></header><div class="ops-calendar-filters"><label class="ops-calendar-search">⌕<input id="calendarSearch" value="${esc(state.calendarFilters.query||'')}" placeholder="Søg rute, chauffør eller bus"></label><select id="calendarBus"><option value="">Alle busser</option>${buses.map(([id,bus])=>`<option value="${id}" ${String(state.calendarFilters.busId)===String(id)?'selected':''}>${esc(bus?.name||'Ukendt bus')}</option>`).join('')}</select><select id="calendarDriver"><option value="">Alle chauffører</option>${drivers.map(([id,name])=>`<option value="${id}" ${String(state.calendarFilters.driverId)===String(id)?'selected':''}>${esc(name||'Ukendt')}</option>`).join('')}</select><select id="calendarStatus"><option value="">Alle statusser</option>${['planned','checkin','underway','completed','cancelled'].map(status=>`<option value="${status}" ${state.calendarFilters.status===status?'selected':''}>${calendarStatusLabel(status)}</option>`).join('')}</select><button class="mini" id="calendarReset">Nulstil</button></div><div class="ops-calendar-body">${body}</div></section><aside class="ops-trip-drawer" id="opsTripDrawer" hidden></aside><div class="ops-drawer-backdrop" id="opsDrawerBackdrop" hidden></div>`;wireOperationsCalendar(conflicts)};

function wireOperationsCalendar(conflicts){$$('[data-calendar-mode]').forEach(button=>button.onclick=()=>{state.calendarMode=button.dataset.calendarMode;if(state.calendarMode==='today')state.calendarDate=calendarDayKey(new Date());renderCalendar()});const move=direction=>{const anchor=calendarAnchor();if(state.calendarMode==='month')anchor.setMonth(anchor.getMonth()+direction);else anchor.setDate(anchor.getDate()+direction*(state.calendarMode==='week'?7:1));state.calendarDate=calendarDayKey(anchor);renderCalendar()};$('#calendarPrevious').onclick=()=>move(-1);$('#calendarNext').onclick=()=>move(1);$('#calendarToday').onclick=()=>{state.calendarDate=calendarDayKey(new Date());renderCalendar()};const updateFilters=()=>{state.calendarFilters={query:$('#calendarSearch').value,busId:$('#calendarBus').value,driverId:$('#calendarDriver').value,status:$('#calendarStatus').value};renderCalendar()};$('#calendarSearch').oninput=event=>{state.calendarFilters.query=event.target.value;clearTimeout(state.calendarSearchTimer);state.calendarSearchTimer=setTimeout(()=>{renderCalendar();const input=$('#calendarSearch');input.focus();input.setSelectionRange(input.value.length,input.value.length)},300)};['#calendarBus','#calendarDriver','#calendarStatus'].forEach(selector=>$(selector).onchange=updateFilters);$('#calendarReset').onclick=()=>{state.calendarFilters={};renderCalendar()};$$('[data-calendar-trip]').forEach(button=>button.onclick=()=>openCalendarDrawer(Number(button.dataset.calendarTrip),conflicts));$$('[data-calendar-mode-day]').forEach(button=>button.onclick=()=>{state.calendarDate=button.dataset.calendarModeDay;state.calendarMode='today';renderCalendar()})}
function openCalendarDrawer(id,conflicts){const trip=state.trips.find(item=>item.id===id),drawer=$('#opsTripDrawer'),backdrop=$('#opsDrawerBackdrop');if(!trip||!drawer)return;const conflictList=[...(conflicts.get(id)||[])],capacity=trip.seatCount||trip.bus?.seatCount||0,status=calendarStatus(trip);drawer.innerHTML=`<button class="ops-drawer-close" id="closeOpsDrawer">×</button><small>DRIFTSDETALJER</small><h2>${esc(trip.title)}</h2><p>${date(trip.departureAt)} · ${calendarStatusLabel(status)}</p><div class="ops-drawer-route"><span>${esc(trip.origin?.name||'–')}</span><i>→</i><span>${esc(trip.destination?.name||'–')}</span></div>${conflictList.length?`<div class="ops-drawer-warning"><strong>Ressourcekonflikt</strong>${conflictList.map(item=>`<span>${esc(item)}</span>`).join('')}</div>`:''}<div class="ops-drawer-details"><div><span>Bus</span><strong>${esc(trip.bus?.name||'Ikke valgt')}</strong></div><div><span>Primær chauffør</span><strong>${esc(trip.primaryDriver||'Ikke valgt')}</strong></div><div><span>Sekundær chauffør</span><strong>${esc(trip.secondaryDriver||'Ikke valgt')}</strong></div><div><span>Salgschef</span><strong>${esc(trip.salesManager||'Ikke valgt')}</strong></div></div><div class="ops-drawer-numbers"><div><strong>${trip.counts.passengers}/${capacity||'–'}</strong><span>Passagerer</span></div><div><strong>${trip.counts.checkedIn}/${trip.counts.passengers}</strong><span>Check-in</span></div><div><strong>${trip.counts.baggage}</strong><span>Bagage</span></div></div><div class="ops-drawer-tasks">${trip.counts.unpaid?`<span>${trip.counts.unpaid} ubetalte salg</span>`:''}${trip.counts.missingReceipts?`<span>${trip.counts.missingReceipts} manglende kvitteringer</span>`:''}${trip.counts.unsettledCash?`<span>${trip.counts.unsettledCash} uafleverede betalinger</span>`:''}</div><div class="ops-drawer-actions"><button class="primary" data-calendar-open="${id}">Åbn tur</button><button data-calendar-checkin="${id}">Åbn check-in</button>${['admin','sales_manager'].includes(state.user.role)?`<button data-calendar-passenger="${id}">+ Passager</button>`:''}${state.user.role==='admin'?`<button data-calendar-economy="${id}">Se økonomi</button>`:''}</div>`;drawer.hidden=false;backdrop.hidden=false;const close=()=>{drawer.hidden=true;backdrop.hidden=true};$('#closeOpsDrawer').onclick=close;backdrop.onclick=close;$('[data-calendar-open]').onclick=()=>openCalendarTrip(id);$('[data-calendar-checkin]').onclick=()=>openCalendarTrip(id,'checkin');$('[data-calendar-passenger]')?.addEventListener('click',()=>openCalendarTrip(id,'passengers',true));$('[data-calendar-economy]')?.addEventListener('click',async()=>{await renderReports();const select=$('#economyTrip');if(select){select.value=String(id);select.dispatchEvent(new Event('change'))}})}
async function openCalendarTrip(id,tab,focusForm=false){await openTrip(id);if(tab){state.tab=tab;renderTrip()}const back=$('#back');if(back)back.onclick=renderCalendar;if(focusForm)setTimeout(()=>$('#passengerForm')?.scrollIntoView({behavior:'smooth',block:'start'}))}

// Role-based dashboard: every employee sees the work that matters now.
function dashboardActionCard(kind,count,title,text,action){return`<button class="dashboard-action-card ${count?'attention':'ok'}" data-dashboard-action="${action}"><span class="dashboard-action-icon">${kind}</span><strong>${count}</strong><div><b>${title}</b><small>${text}</small></div><i>›</i></button>`}
function dashboardQuickButton(icon,title,text,action){return`<button data-dashboard-quick="${action}"><span>${icon}</span><div><strong>${title}</strong><small>${text}</small></div><b>›</b></button>`}
function dashboardNextTrip(trip,conflicts){if(!trip)return'<div class="dashboard-no-trip"><strong>Ingen kommende ture</strong><span>Der er ingen aktive afgange i kalenderen.</span></div>';const status=calendarStatus(trip),capacity=trip.seatCount||trip.bus?.seatCount||0,pct=trip.counts.passengers?Math.round(trip.counts.checkedIn/trip.counts.passengers*100):0;return`<div class="dashboard-next-trip"><div class="dashboard-next-time"><small>${copenhagenFormat(trip.departureAt,{weekday:'short',day:'numeric',month:'short'})}</small><strong>${copenhagenTime(trip.departureAt)}</strong><span>${calendarStatusLabel(status)}</span></div><div class="dashboard-next-main"><h3>${esc(trip.title)}</h3><p>${esc(trip.origin?.name||'–')} → ${esc(trip.destination?.name||'–')}</p><div><span>${esc(trip.bus?.name||'Ingen bus')}</span><span>${esc(trip.primaryDriver||'Ingen chauffør')}</span></div></div><div class="dashboard-next-progress"><span><b>${trip.counts.checkedIn}</b> af ${trip.counts.passengers} checket ind</span><i><em style="width:${pct}%"></em></i><small>${trip.counts.passengers}/${capacity||'–'} sæder · ${trip.counts.baggage} bagage</small></div>${conflicts.get(trip.id)?.size?'<div class="dashboard-next-warning">! Ressourcekonflikt</div>':''}<div class="dashboard-next-actions"><button class="primary" data-dashboard-open-trip="${trip.id}">Åbn tur</button><button data-dashboard-checkin="${trip.id}">Check-in</button></div></div>`}

renderDashboard=async function(){state.trip=null;activate('dashboard');setTitle('Mit overblik','DAGENS DRIFT');let dashboard;try{dashboard=await api('/api/dashboard')}catch(error){toast(error.message);return}if(!$('.nav[data-view="dashboard"]')?.classList.contains('active'))return;const now=new Date(),activeTrips=state.trips.filter(trip=>!['completed','cancelled'].includes(calendarStatus(trip))).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt)),next=activeTrips.find(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000>Date.now()),todayTrips=state.trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(now)).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt)),conflicts=calendarConflicts(activeTrips),conflictCount=activeTrips.filter(trip=>conflicts.get(trip.id)?.size).length,hour=now.getHours(),greeting=hour<10?'Godmorgen':hour<18?'Goddag':'Godaften',firstName=state.user.name.split(' ')[0],role=state.user.role;let actions='',quick='';if(role==='admin'){actions=dashboardActionCard('!',conflictCount,'Planlægningskonflikter','Bus eller chauffør overlapper','calendar')+dashboardActionCard('▧',dashboard.pendingExpenses,'Udgifter afventer','Kræver godkendelse','economy')+dashboardActionCard('⌑',dashboard.missingReceipts,'Kvitteringer mangler','Kan ikke godkendes endnu','economy')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Uafleverede betalinger','Kontanter hos personale','economy');quick=dashboardQuickButton('+','Opret ny tur','Planlæg afgang og bemanding','new-trip')+dashboardQuickButton('□','Åbn kalender','Se hele driften','calendar')+dashboardQuickButton('♙','Chauffører','Administrer personale','drivers')+dashboardQuickButton('◫','Salg og økonomi','Kontanter, udgifter og resultat','economy')}else if(role==='driver'){actions=dashboardActionCard('✓',next?Math.max(0,next.counts.passengers-next.counts.checkedIn):0,'Passagerer afventer','På din næste tur','checkin')+dashboardActionCard('▣',dashboard.openBaggage,'Aktiv bagage','Skal håndteres på ture','calendar')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Kontanter hos dig','Skal senere afstemmes','cash')+dashboardActionCard('⌑',dashboard.missingReceipts,'Kvitteringer mangler','Tilføj bilag på turen','expenses');quick=dashboardQuickButton('✓','Åbn check-in','Start med næste tur','checkin')+dashboardQuickButton('□','Mine ture','Åbn driftskalenderen','calendar')+dashboardQuickButton('⌑','Registrer udgift','Tag billede af kvittering','expenses')+dashboardQuickButton('¤','Kontantafstemning','Se dit kontantansvar','cash')}else{actions=dashboardActionCard('□',todayTrips.length,'Dagens ture','Du kan arbejde ved startstederne','calendar')+dashboardActionCard('!',dashboard.unpaid,'Ubetalte salg','Billetter og bagage','checkin')+dashboardActionCard('▣',dashboard.openBaggage,'Aktiv bagage','Modtagelse og udlevering','calendar')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Kontanter hos dig','Skal senere afstemmes','cash');quick=dashboardQuickButton('✓','Åbn check-in','Betjen næste startsted','checkin')+dashboardQuickButton('+','Sælg billet','Tilføj passager på næste tur','passenger')+dashboardQuickButton('▣','Registrer bagage','Modtag bagage ved startstedet','baggage')+dashboardQuickButton('¤','Kontantafstemning','Se modtagne betalinger','cash')}
  const roleText=role==='admin'?'Her er virksomhedens vigtigste opgaver lige nu.':role==='driver'?'Her er dine afgange og opgaver for i dag.':'Her er dagens afgange og check-in ved alle stop med gæster.';
  $('#view').innerHTML=`<section class="dashboard-welcome"><div><small>${now.toLocaleDateString('da-DK',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</small><h2>${greeting}, ${esc(firstName)}</h2><p>${roleText}</p></div><span class="dashboard-live"><i></i> Live driftsstatus</span></section><section class="dashboard-action-section"><header><h3>Kræver handling</h3><span>${[...new DOMParser().parseFromString(actions,'text/html').querySelectorAll('.attention')].length} områder</span></header><div class="dashboard-action-grid">${actions}</div></section><div class="dashboard-workspace"><section class="dashboard-next-panel"><header><div><small>NÆSTE AFGANG</small><h3>${next?'Klar til drift':'Ingen planlagt afgang'}</h3></div><button data-dashboard-action="calendar">Se kalender →</button></header>${dashboardNextTrip(next,conflicts)}</section><section class="dashboard-quick-panel"><header><small>HURTIGE HANDLINGER</small><h3>Hvad vil du gøre?</h3></header><div>${quick}</div></section></div><div class="dashboard-lower"><section class="dashboard-today-panel"><header><div><small>DAGENS TIDSLINJE</small><h3>${todayTrips.length} ${todayTrips.length===1?'afgang':'afgange'} i dag</h3></div><button data-dashboard-action="calendar">Åbn kalender</button></header><div>${todayTrips.length?todayTrips.map(trip=>calendarTripCard(trip,conflicts,true)).join(''):'<div class="dashboard-empty-small">Ingen ture i dag</div>'}</div></section><section class="dashboard-money-panel"><header><small>${role==='admin'?'DAGENS SALG':'DIT KONTANTANSVAR'}</small><h3>${role==='admin'?'Billetter og bagage':'Kontanter hos dig'}</h3></header>${role==='admin'?`<div class="dashboard-sales-grid"><div><span>Billetter · ${dashboard.todayTicketSales}</span>${economyValues(dashboard.todayTicketRevenue,'all',true)}</div><div><span>Bagage · ${dashboard.todayBaggageSales}</span>${economyValues(dashboard.todayBaggageRevenue,'all',true)}</div></div>`:`<div class="dashboard-cash-total"><span>${dashboard.cashHeld.payments} betalinger</span>${economyValues(dashboard.cashHeld,'all',true)}</div>`}${role==='admin'&&dashboard.cashHeld.byPerson.length?`<div class="dashboard-holder-list">${dashboard.cashHeld.byPerson.map(person=>`<div><span>${esc(person.userName)}<small>${person.payments} betalinger</small></span><b>${money(person.DKK,'DKK')} · ${money(person.EUR,'EUR')}</b></div>`).join('')}</div>`:''}<button data-dashboard-action="${role==='admin'?'economy':'cash'}">${role==='admin'?'Åbn salg og økonomi':'Åbn kontantafstemning'} →</button></section></div>`;wireRoleDashboard(next)};

function wireRoleDashboard(next){const act=async action=>{if(action==='calendar')return renderCalendar();if(action==='economy')return renderReports();if(action==='drivers')return renderDrivers();if(action==='new-trip')return $('#newTrip').click();if(!next)return toast('Der er ingen kommende tur');if(action==='checkin')return openDashboardTrip(next.id,'checkin');if(action==='passenger')return openDashboardTrip(next.id,'passengers',true);if(action==='baggage')return openDashboardTrip(next.id,'baggage');if(action==='expenses')return openDashboardTrip(next.id,'expenses');if(action==='cash')return openDashboardTrip(next.id,'settlements')};$$('[data-dashboard-action]').forEach(button=>button.onclick=()=>act(button.dataset.dashboardAction));$$('[data-dashboard-quick]').forEach(button=>button.onclick=()=>act(button.dataset.dashboardQuick));$$('[data-dashboard-open-trip]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.dashboardOpenTrip)));$$('[data-dashboard-checkin]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.dashboardCheckin),'checkin'));$$('.dashboard-today-panel [data-calendar-trip]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.calendarTrip)))}
async function openDashboardTrip(id,tab,focusForm=false){await openTrip(id);if(tab){state.tab=tab;renderTrip()}const back=$('#back');if(back)back.onclick=renderDashboard;if(focusForm)setTimeout(()=>$('#passengerForm')?.scrollIntoView({behavior:'smooth',block:'start'}))}

// Administratorens turudgifter vises som adskilte mapper, én planlagt tur ad gangen.
const reportsBeforeTripExpenseBrowser=renderReports;
renderReports=async function(){
  await reportsBeforeTripExpenseBrowser();
  if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{
    const report=await api('/api/reports');
    renderTripExpenseBrowser(report);
  }catch(error){toast(error.message)}
};

function expenseTotalsForTrip(expenses,status){
  return ['DKK','EUR'].reduce((totals,currency)=>{
    totals[currency]=expenses.filter(expense=>(!status||(expense.status||'pending')===status)&&expense.currency===currency).reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    return totals;
  },{});
}

function plannedExpenseTrips(){
  const now=Date.now(),trips=(state.trips||[]).filter(trip=>trip.status!=='cancelled');
  const active=trips.filter(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000>=now).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt));
  const previous=trips.filter(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000<now).sort((a,b)=>new Date(b.departureAt)-new Date(a.departureAt));
  return [...active,...previous];
}

function renderTripExpenseBrowser(report){
  $('#tripExpenseBrowser')?.remove();
  [...$$('.report-section')].find(panel=>panel.querySelector('h2')?.textContent==='Turudgifter og kvitteringer')?.remove();
  $('.expense-approval-panel')?.remove();
  const trips=plannedExpenseTrips(),expenses=report.expenses||[];
  const anchor=$('.advanced-trip-economy')||$('.economy-control');
  if(!anchor)return;
  if(!trips.length){
    anchor.insertAdjacentHTML('afterend','<section class="trip-expense-browser empty-trip-expenses" id="tripExpenseBrowser"><span class="trip-expense-folder-icon">▧</span><div><small>TURUDGIFTSMAPPER</small><h2>Ingen planlagte ture</h2><p>Opret en tur i kalenderen. Derefter får turen automatisk sin egen udgiftsmappe.</p></div></section>');
    return;
  }
  const firstWithAction=trips.find(trip=>expenses.some(expense=>expense.tripId===trip.id&&((expense.status||'pending')==='pending'||!expense.receiptFile))),firstUpcoming=trips.find(trip=>new Date(trip.departureAt)>new Date());
  if(!trips.some(trip=>trip.id===Number(state.expenseTripId)))state.expenseTripId=firstWithAction?.id||firstUpcoming?.id||trips[0].id;
  const selected=trips.find(trip=>trip.id===Number(state.expenseTripId)),selectedIndex=trips.findIndex(trip=>trip.id===selected.id),selectedExpenses=expenses.filter(expense=>expense.tripId===selected.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const approved=expenseTotalsForTrip(selectedExpenses,'approved'),pending=expenseTotalsForTrip(selectedExpenses,'pending'),missing=selectedExpenses.filter(expense=>!expense.receiptFile).length,privateOpen=selectedExpenses.filter(expense=>(expense.paymentMethod||'cash')==='private'&&(expense.reimbursementStatus||'pending')!=='paid'&&(expense.status||'pending')!=='rejected').length;
  const tripButtons=trips.map(trip=>{const tripExpenses=expenses.filter(expense=>expense.tripId===trip.id),tripPending=tripExpenses.filter(expense=>(expense.status||'pending')==='pending').length,tripMissing=tripExpenses.filter(expense=>!expense.receiptFile).length;return`<button class="trip-expense-folder ${trip.id===selected.id?'active':''}" data-expense-trip="${trip.id}"><span class="trip-expense-folder-icon">▧</span><span><strong>${esc(trip.title)}</strong><small>${date(trip.departureAt)} · ${tripExpenses.length} udgifter</small></span>${tripPending||tripMissing?`<b>${tripPending+tripMissing}</b>`:'<i>✓</i>'}</button>`}).join('');
  const options=trips.map(trip=>`<option value="${trip.id}" ${trip.id===selected.id?'selected':''}>${copenhagenDate(trip.departureAt)} · ${esc(trip.title)}</option>`).join('');
  const rows=selectedExpenses.length?selectedExpenses.map(adminTripExpenseCard).join(''):'<div class="trip-expense-empty"><span>✓</span><strong>Ingen udgifter på denne tur</strong><p>Når en chauffør eller administrator registrerer en udgift, vises den kun i denne mappe.</p></div>';
  anchor.insertAdjacentHTML('afterend',`<section class="trip-expense-browser" id="tripExpenseBrowser"><header class="trip-expense-browser-head"><div><small>ADMINISTRATOR · TURUDGIFTSMAPPER</small><h2>Udgifter adskilt efter tur</h2><p>Vælg en tur for kun at se dens udgifter, bilag og godkendelser.</p></div><div class="trip-expense-navigation"><button id="previousExpenseTrip" aria-label="Forrige turs udgifter" ${selectedIndex===0?'disabled':''}>‹</button><label>Vælg tur<select id="expenseTripNavigator">${options}</select></label><button id="nextExpenseTrip" aria-label="Næste turs udgifter" ${selectedIndex===trips.length-1?'disabled':''}>›</button></div></header><div class="trip-expense-browser-layout"><nav class="trip-expense-folders" aria-label="Planlagte tures udgiftsmapper">${tripButtons}</nav><div class="trip-expense-selected"><header><div><small>${calendarStatusLabel(calendarStatus(selected))} · ${date(selected.departureAt)}</small><h3>${esc(selected.title)}</h3><p>${esc(selected.origin?.name||'–')} → ${esc(selected.destination?.name||'–')} · ${esc(selected.bus?.name||'Ingen bus')}</p></div><button class="mini" id="openSelectedTripExpenses">Åbn turens udgiftsmappe →</button></header><div class="trip-expense-totals"><div class="approved"><span>Godkendt</span>${economyValues(approved,'all',true)}</div><div class="pending"><span>Afventer</span>${economyValues(pending,'all',true)}</div><div class="${missing?'attention':''}"><span>Mangler kvittering</span><strong>${missing}</strong></div><div class="${privateOpen?'attention':''}"><span>Private udlæg åbne</span><strong>${privateOpen}</strong></div></div><div class="admin-trip-expense-list">${rows}</div></div></div></section>`);
  wireTripExpenseBrowser(report,trips,selectedIndex,selected.id);
}

function adminTripExpenseCard(expense){
  const status=expense.status||'pending',missing=!expense.receiptFile,privatePending=(expense.paymentMethod||'cash')==='private'&&status==='approved'&&(expense.reimbursementStatus||'pending')!=='paid';
  return`<article class="admin-trip-expense-card"><span class="admin-expense-status ${status}">${expenseStatusLabel(status)}</span><div class="admin-expense-main"><small>${date(expense.expenseDate||expense.createdAt)} · ${expenseMethodLabel(expense.paymentMethod||'cash')}</small><h4>${esc(expense.category)}</h4><p>${esc(expense.description||'Ingen beskrivelse')}</p><span>Betalt af <b>${esc(expense.paidByName||expense.createdByName||'Ukendt')}</b> · registreret af ${esc(expense.createdByName||'Ukendt')}</span></div><strong class="admin-expense-amount">${money(expense.amount,expense.currency)}</strong><div class="admin-expense-receipt ${missing?'missing':''}">${missing?'<span>Kvittering mangler</span>':`<a href="/api/expenses/${expense.id}/receipt" target="_blank">Se kvittering ↗</a>`}</div><div class="admin-expense-actions">${status==='pending'?`<button class="mini done" data-admin-approve-expense="${expense.id}" ${missing?'disabled title="Kvittering mangler"':''}>Godkend</button><button class="mini danger" data-admin-reject-expense="${expense.id}">Afvis</button>`:''}${privatePending?`<button class="mini reimburse" data-admin-reimburse-expense="${expense.id}">Marker tilbagebetalt</button>`:''}</div>${expense.reviewNote?`<div class="admin-expense-note"><b>Kommentar:</b> ${esc(expense.reviewNote)}</div>`:''}</article>`;
}

function wireTripExpenseBrowser(report,trips,index,tripId){
  state.adminExpenseReport=report;
  $$('[data-expense-trip]').forEach(button=>button.onclick=()=>{state.expenseTripId=Number(button.dataset.expenseTrip);renderTripExpenseBrowser(report)});
  $('#expenseTripNavigator').onchange=event=>{state.expenseTripId=Number(event.target.value);renderTripExpenseBrowser(report)};
  $('#previousExpenseTrip').onclick=()=>{if(index>0){state.expenseTripId=trips[index-1].id;renderTripExpenseBrowser(report)}};
  $('#nextExpenseTrip').onclick=()=>{if(index<trips.length-1){state.expenseTripId=trips[index+1].id;renderTripExpenseBrowser(report)}};
  $('#openSelectedTripExpenses').onclick=async()=>{await openTrip(tripId);state.tab='expenses';renderTrip();const back=$('#back');if(back)back.onclick=renderReports};
  $$('[data-admin-approve-expense]').forEach(button=>button.onclick=()=>reviewAdminTripExpense(Number(button.dataset.adminApproveExpense),'approved'));
  $$('[data-admin-reject-expense]').forEach(button=>button.onclick=()=>reviewAdminTripExpense(Number(button.dataset.adminRejectExpense),'rejected'));
  $$('[data-admin-reimburse-expense]').forEach(button=>button.onclick=()=>reimburseAdminTripExpense(Number(button.dataset.adminReimburseExpense)));
}

async function reviewAdminTripExpense(id,status){
  let reviewNote='';
  if(status==='rejected'){const reason=prompt('Hvorfor afvises udgiften?');if(reason===null)return;reviewNote=reason}
  try{await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({status,reviewNote})});toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');await renderReports()}catch(error){toast(error.message)}
}

async function reimburseAdminTripExpense(id){
  if(!confirm('Bekræft, at det private udlæg er tilbagebetalt.'))return;
  try{await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({reimbursementStatus:'paid'})});toast('Udlægget er markeret som tilbagebetalt');await renderReports()}catch(error){toast(error.message)}
}

// Every baggage record is created with a trip-specific documentation photo.
baggageForm=function(){return`<section class="panel baggage-entry-panel"><div class="panel-head"><div><small>BAGAGEDOKUMENTATION</small><h2>Registrer bagage</h2></div><span class="baggage-photo-required">Foto påkrævet</span></div><form class="form" id="baggageForm" style="padding:20px"><label>Afsender<input name="senderName" required></label><label>Modtager<input name="recipientName" required></label><label>Telefon<input name="phone" required></label><label>Fra<select name="pickupStopId">${stopOptions()}</select></label><label>Til<select name="destinationStopId">${stopOptions()}</select></label><label>Antal kolli<input name="pieces" type="number" min="1" value="1" required></label><label>Beskrivelse<input name="description" placeholder="Kuffert, pakke …"></label><label class="wide receipt-capture baggage-photo-capture"><span>Foto af bagagen <small>obligatorisk dokumentation</small></span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required><b>Tag billede eller vælg foto</b><em>JPG, PNG eller WebP · ingen fast filgrænse</em></label><label>Betaling<select name="paymentStatus"><option value="unpaid">Ikke betalt</option><option value="pay_dk">Betaler i DK</option><option value="pay_mk">Betaler i MK</option><option value="cash">Betalt kontant</option></select></label><label>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label>Kontant beløb<input name="cashAmount" type="number" min="0" step="0.01" value="0"></label><label class="wide">Bemærkning<textarea name="notes" placeholder="Kendetegn, farve eller anden dokumentation"></textarea></label><button class="primary wide">Gem bagage med foto</button></form></section>`};

wireBaggageForm=function(){const form=$('#baggageForm'),photoInput=form.elements.photo,photoLabel=form.querySelector('.baggage-photo-capture b');photoInput.onchange=()=>{photoLabel.textContent=photoInput.files[0]?.name||'Tag billede eller vælg foto'};form.onsubmit=async event=>{event.preventDefault();const file=photoInput.files[0];if(!file)return toast('Tag eller vælg et billede af bagagen');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Bagagebilledet skal være JPG, PNG eller WebP');try{const payload=Object.fromEntries(new FormData(form));delete payload.photo;Object.assign(payload,{photoName:file.name,photoType:file.type,photoData:await fileAsDataUrl(file)});const baggage=await api(`/api/trips/${state.trip.trip.id}/baggage`,{method:'POST',body:JSON.stringify(payload)});state.trip.baggage.push(baggage);toast(state.user.role==='driver'?'Bagagen er modtaget · pengene står hos dig':'Bagagen og billeddokumentationen er gemt');renderTrip()}catch(error){toast(error.message)}}};

const renderTabBeforeBaggagePhotos=renderTab;
renderTab=function(){renderTabBeforeBaggagePhotos();if(state.tab!=='baggage')return;$$('#tabContent [data-bag]').forEach(control=>{const item=state.trip.baggage.find(record=>record.id===Number(control.dataset.bag)),cell=control.closest('tr')?.cells[0];if(!item||!cell||cell.querySelector('.baggage-photo-link,.baggage-photo-missing'))return;cell.insertAdjacentHTML('beforeend',item.photoFile?`<a class="baggage-photo-link" href="/api/baggage/${item.id}/photo" target="_blank">▣ Se bagagefoto ↗</a>`:'<span class="baggage-photo-missing">Foto mangler</span>')})};

const reportsBeforeBaggagePhotos=renderReports;
renderReports=async function(){await reportsBeforeBaggagePhotos();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports'),panel=[...$$('.report-section')].find(section=>section.querySelector('h2')?.textContent==='Bagagesalg');if(!panel)return;[...panel.querySelectorAll('tbody tr')].forEach((row,index)=>{const item=report.baggage[index],cell=row.cells[0];if(!item||!cell||cell.querySelector('.baggage-photo-link,.baggage-photo-missing'))return;cell.insertAdjacentHTML('beforeend',item.photoFile?`<a class="baggage-photo-link" href="/api/baggage/${item.id}/photo" target="_blank">▣ Se dokumentationsfoto ↗</a>`:'<span class="baggage-photo-missing">Foto mangler</span>')})}catch(error){toast(error.message)}};

// Assigned drivers can sell a paid ticket in the bus. The cash is always assigned to the logged-in driver.
const renderTabBeforeDriverTicketSales=renderTab;
renderTab=function(){renderTabBeforeDriverTicketSales();if(state.user.role!=='driver'||state.tab!=='passengers')return;const layout=$('.passenger-layout');if(!layout)return;while(layout.children.length>1)layout.lastElementChild.remove();layout.insertAdjacentHTML('beforeend',passengerForm());const form=$('#passengerForm'),panel=form.closest('.panel'),heading=panel.querySelector('.panel-head');panel.classList.add('driver-ticket-panel');heading.innerHTML=`<div><small>BILLETSALG I BUSSEN</small><h2>Sælg ny billet</h2></div><span>Kontanter hos ${esc(state.user.name)}</span>`;heading.insertAdjacentHTML('afterend',`<div class="driver-ticket-note"><b>¤</b><span>Betalingen registreres automatisk hos dig og kommer med i turens kontantafstemning.</span></div>`);form.paymentStatus.innerHTML='<option value="cash">Betalt kontant i bussen</option>';form.paymentStatus.value='cash';form.querySelector('[data-free-ticket-field]')?.remove();const preferredStop=Number(state.currentCheckinStop)||state.trip.trip.originId;if([...form.pickupStopId.options].some(option=>Number(option.value)===preferredStop))form.pickupStopId.value=String(preferredStop);form.querySelector('button.primary').textContent='Sælg billet i bussen';wirePassengerForm();form.paymentStatus.dispatchEvent(new Event('change'))};

const checkInModeBeforeDriverTicketSales=renderCheckInMode;
renderCheckInMode=function(){checkInModeBeforeDriverTicketSales();if(state.user.role!=='driver'||!$('.checkin-command'))return;$('.checkin-command').insertAdjacentHTML('afterend','<button class="driver-ticket-shortcut" id="driverTicketShortcut"><b>＋</b><span><strong>Sælg billet i bussen</strong><small>Vælg et ledigt sæde og registrer betalingen</small></span><i>→</i></button>');$('#driverTicketShortcut').onclick=()=>{state.tab='passengers';state.selectedSeat=null;renderTrip()}};

const renderTabBeforeDriverBaggageIntake=renderTab;
renderTab=function(){renderTabBeforeDriverBaggageIntake();if(state.user.role!=='driver'||state.tab!=='baggage'||$('#baggageForm'))return;const layout=$('#tabContent .grid2');if(!layout)return;while(layout.children.length>1)layout.lastElementChild.remove();layout.insertAdjacentHTML('beforeend',baggageForm());const form=$('#baggageForm'),panel=form.closest('.panel'),heading=panel.querySelector('.panel-head');panel.classList.add('driver-baggage-panel');heading.innerHTML=`<div><small>BAGAGEMODTAGELSE I BUSSEN</small><h2>Modtag ny bagage</h2></div><span>Kontanter hos ${esc(state.user.name)}</span>`;heading.insertAdjacentHTML('afterend','<div class="driver-baggage-note"><b>▣</b><span>Tag et billede af bagagen. Betalingen registreres automatisk hos dig og kommer med i turens kontantafstemning.</span></div>');form.paymentStatus.innerHTML='<option value="cash">Betalt kontant i bussen</option>';form.paymentStatus.value='cash';const preferredStop=Number(state.currentCheckinStop)||state.trip.trip.originId;if([...form.pickupStopId.options].some(option=>Number(option.value)===preferredStop))form.pickupStopId.value=String(preferredStop);form.querySelector('button.primary').textContent='Modtag bagage i bussen';wireBaggageForm()};

const checkInModeBeforeDriverBaggageIntake=renderCheckInMode;
renderCheckInMode=function(){checkInModeBeforeDriverBaggageIntake();if(state.user.role!=='driver'||!$('#driverTicketShortcut'))return;$('#driverTicketShortcut').insertAdjacentHTML('afterend','<button class="driver-ticket-shortcut driver-baggage-shortcut" id="driverBaggageShortcut"><b>▣</b><span><strong>Modtag bagage i bussen</strong><small>Tag foto og registrer betalingen</small></span><i>→</i></button>');$('#driverBaggageShortcut').onclick=()=>{state.tab='baggage';renderTrip()}};

// A trip always starts in Copenhagen or Tetovo. Other stops remain available for pickup and destination.
function isFixedStartPoint(stop){return ['københavn','tetovo'].includes(String(stop?.name||'').trim().toLocaleLowerCase('da-DK'))}
const newTripBeforeFixedStartPoint=$('#newTrip').onclick;
$('#newTrip').onclick=()=>{newTripBeforeFixedStartPoint();const form=$('#createTrip');if(!form)return;const startPoints=state.stops.filter(isFixedStartPoint);form.originId.innerHTML=startPoints.length?startPoints.map(stop=>`<option value="${stop.id}">${esc(stop.name)}</option>`).join(''):'<option value="">Opret København eller Tetovo først</option>';form.originId.closest('label').insertAdjacentHTML('beforeend','<small class="fixed-start-note">Fast startpunkt: København eller Tetovo</small>');form.departureAt?.closest('label')?.insertAdjacentHTML('beforeend','<small class="fixed-start-note">Tid indtastes som København-tid (CET/CEST)</small>')};

// Passenger pickup is independent of the trip origin and keeps every registered stop available.
const passengerFormBeforeFlexiblePickup=passengerForm;
passengerForm=function(){const note=state.user.role==='sales_manager'?'Nye billetter sælges kun fra turens startsted':'Alle oprettede opsamlingssteder kan vælges';return passengerFormBeforeFlexiblePickup().replace('</select></label><label>Til','</select><small class="passenger-pickup-note">'+note+'</small></label><label>Til')};

function tripHasLinkedRecords(){return Boolean(state.trip.passengers.length||state.trip.baggage.length||state.trip.expenses.length||state.trip.settlements.length)}
function showCancelTripDialog(){const trip=state.trip.trip;$('#modalBody').innerHTML=`<h2>Annuller tur</h2><p class="muted">${esc(trip.title)} bevares med passagerer, bagage, betalinger, udgifter og historik.</p><form class="form trip-lifecycle-form" id="cancelTripForm"><label class="wide">Begrundelse<textarea name="cancellationReason" minlength="3" required placeholder="Hvorfor annulleres turen?"></textarea></label><div class="wide lifecycle-warning"><strong>Turens drift stoppes</strong><span>Chauffører og salgschef kan ikke længere sælge, modtage bagage eller udføre check-in.</span></div><button class="danger-button wide">Annuller tur</button></form>`;$('#cancelTripForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({status:'cancelled',cancellationReason:event.target.cancellationReason.value})});state.trip.trip=updated;const overview=state.trips.find(item=>item.id===trip.id);if(overview)Object.assign(overview,updated);state.tab='passengers';$('#modal').close();toast('Turen er annulleret og historikken er bevaret');renderTrip()}catch(error){toast(error.message)}};$('#modal').showModal()}
function showDeleteTripDialog(){const trip=state.trip.trip;$('#modalBody').innerHTML=`<h2>Slet tur permanent</h2><p class="muted">Dette kan ikke fortrydes. Skriv <strong>SLET</strong> for at bekræfte sletning af ${esc(trip.title)}.</p><form class="form trip-lifecycle-form" id="deleteTripForm"><label class="wide">Bekræftelse<input name="confirmation" autocomplete="off" required placeholder="Skriv SLET"></label><div class="wide lifecycle-warning danger"><strong>Permanent sletning</strong><span>Kun en tom tur uden registreringer kan slettes.</span></div><button class="danger-button wide">Slet tur permanent</button></form>`;$('#deleteTripForm').onsubmit=async event=>{event.preventDefault();if(event.target.confirmation.value.trim().toUpperCase()!=='SLET')return toast('Skriv SLET for at bekræfte');try{await api(`/api/trips/${trip.id}`,{method:'DELETE'});state.trips=state.trips.filter(item=>item.id!==trip.id);state.trip=null;$('#modal').close();toast('Turen er slettet permanent');renderCalendar()}catch(error){toast(error.message)}};$('#modal').showModal()}
const renderTripBeforeLifecycleActions=renderTrip;
renderTrip=function(){renderTripBeforeLifecycleActions();const trip=state.trip?.trip;if(!trip)return;if(trip.status==='cancelled'&&state.tab==='checkin'){state.tab='passengers';renderTrip();return}const linked=tripHasLinkedRecords(),hero=$('.detail-hero');if(trip.status==='cancelled'){const pill=hero?.querySelector('.pill');if(pill){pill.textContent='Annulleret';pill.classList.add('cancelled')}['#capacityForm','#tripBusAssignment','.trip-driver-assignment','.trip-sales-assignment'].forEach(selector=>$(selector)?.remove());$('[data-checkin-tab]')?.remove();$('#passengerForm')?.closest('.panel')?.remove();$('#baggageForm')?.closest('.panel')?.remove();$$('[data-check],[data-fast-check],[data-pay-passenger],[data-no-show],.bag-status').forEach(control=>control.disabled=true);hero?.insertAdjacentHTML('afterend',`<section class="trip-cancelled-banner"><div><small>TUREN ER ANNULLERET</small><strong>${esc(trip.cancellationReason||'Ingen begrundelse angivet')}</strong><span>${trip.cancelledAt?date(trip.cancelledAt):''}${trip.cancelledByName?` · af ${esc(trip.cancelledByName)}`:''}</span></div><span>Historik og økonomi er bevaret</span></section>`)}if(state.user.role!=='admin')return;const actions=`<section class="trip-lifecycle-actions ${trip.status==='cancelled'?'is-cancelled':''}"><div><small>TURADMINISTRATION</small><strong>${trip.status==='cancelled'?'Annulleret tur':'Annullering og sletning'}</strong><span>${linked?'Turen har registrerede data og kan kun annulleres.':'Turen er tom og kan slettes permanent.'}</span></div>${trip.status!=='cancelled'?'<button class="cancel-trip-button" id="cancelTripButton">Annuller tur</button>':''}${!linked?'<button class="delete-trip-button" id="deleteTripButton">Slet permanent</button>':'<span class="delete-trip-locked">🔒 Sletning låst</span>'}</section>`;(hero||$('#view')).insertAdjacentHTML('afterend',actions);$('#cancelTripButton')?.addEventListener('click',showCancelTripDialog);$('#deleteTripButton')?.addEventListener('click',showDeleteTripDialog)};

const openCalendarDrawerBeforeLifecycle=openCalendarDrawer;
openCalendarDrawer=function(id,conflicts){openCalendarDrawerBeforeLifecycle(id,conflicts);const trip=state.trips.find(item=>item.id===id);if(trip?.status!=='cancelled')return;$('[data-calendar-checkin]')?.remove();$('[data-calendar-passenger]')?.remove();$('.ops-drawer-actions')?.insertAdjacentHTML('beforebegin',`<div class="ops-drawer-warning"><strong>Turen er annulleret</strong><span>${esc(trip.cancellationReason||'Historikken er bevaret')}</span></div>`)};

// Corrections keep an audit trail and never silently delete operational history.
function correctionStopOptions(selected){return state.stops.map(stop=>`<option value="${stop.id}" ${Number(selected)===stop.id?'selected':''}>${esc(stop.name)}</option>`).join('')}
function correctionHistory(record){const history=record.editHistory||[];return history.length?`<div class="correction-history"><strong>Seneste rettelser</strong>${[...history].reverse().slice(0,3).map(item=>`<span>${date(item.editedAt)} · ${esc(item.editedByName||'Ukendt')}<small>${esc(item.reason)}</small></span>`).join('')}</div>`:''}
function correctionSeatOptions(passenger){return state.trip.seats.filter(seat=>!seat.passengerId||seat.passengerId===passenger.id).map(seat=>`<option value="${seat.number}" ${seat.number===passenger.seatNumber?'selected':''}>Sæde ${seat.number} · ${seat.type==='front'?'Front':seat.type==='table'?'Bord':'Standard'}</option>`).join('')}
function showPassengerCorrection(id){const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger)return;const cash=passenger.paymentStatus==='cash';$('#modalBody').innerHTML=`<h2>Ret passager</h2><p class="muted">Brug kun rettelsen, når oplysninger er tastet forkert. Ændringen gemmes i historikken.</p><form class="form correction-form" id="passengerCorrectionForm"><label>Navn<input name="name" value="${esc(passenger.name)}" required></label><label>Telefon<input name="phone" value="${esc(passenger.phone)}" required></label><label>Fra<select name="pickupStopId">${correctionStopOptions(passenger.pickupStopId)}</select></label><label>Til<select name="destinationStopId">${correctionStopOptions(passenger.destinationStopId)}</select></label><label class="wide">Sæde<select name="seatNumber">${correctionSeatOptions(passenger)}</select></label>${cash?`<label>Kontantbeløb<input name="cashAmount" type="number" min="0.01" step="0.01" value="${passenger.cashAmount}" required></label><label>Valuta<select name="paymentCurrency"><option value="DKK" ${passenger.paymentCurrency==='DKK'?'selected':''}>DKK</option><option value="EUR" ${passenger.paymentCurrency==='EUR'?'selected':''}>EUR</option></select></label>`:''}${passenger.paymentStatus==='free'?`<label class="wide">Begrundelse for gratis billet<input name="freeTicketReason" value="${esc(passenger.freeTicketReason||'')}"></label>`:''}<label class="wide correction-reason">Hvorfor rettes registreringen?<textarea name="correctionReason" minlength="3" required placeholder="F.eks. forkert telefonnummer eller sæde"></textarea></label><button class="primary wide">Gem rettelse</button></form>${correctionHistory(passenger)}`;$('#passengerCorrectionForm').onsubmit=event=>submitCorrection(event,'passengers',passenger);$('#modal').showModal()}
function showBaggageCorrection(id){const item=state.trip.baggage.find(record=>record.id===id);if(!item)return;const cash=item.paymentStatus==='cash';$('#modalBody').innerHTML=`<h2>Ret bagage</h2><p class="muted">Foto og bagagehistorik bevares. Rettelsen registreres med medarbejder og tidspunkt.</p><form class="form correction-form" id="baggageCorrectionForm"><label>Afsender<input name="senderName" value="${esc(item.senderName)}" required></label><label>Modtager<input name="recipientName" value="${esc(item.recipientName||'')}" required></label><label>Telefon<input name="phone" value="${esc(item.phone)}" required></label><label>Fra<select name="pickupStopId">${correctionStopOptions(item.pickupStopId)}</select></label><label>Til<select name="destinationStopId">${correctionStopOptions(item.destinationStopId)}</select></label><label>Antal kolli<input name="pieces" type="number" min="1" value="${item.pieces}" required></label><label>Beskrivelse<input name="description" value="${esc(item.description||'')}"></label>${cash?`<label>Kontantbeløb<input name="cashAmount" type="number" min="0.01" step="0.01" value="${item.cashAmount}" required></label><label>Valuta<select name="paymentCurrency"><option value="DKK" ${item.paymentCurrency==='DKK'?'selected':''}>DKK</option><option value="EUR" ${item.paymentCurrency==='EUR'?'selected':''}>EUR</option></select></label>`:''}<label class="wide">Bemærkning<textarea name="notes">${esc(item.notes||'')}</textarea></label><label class="wide correction-reason">Hvorfor rettes registreringen?<textarea name="correctionReason" minlength="3" required placeholder="F.eks. forkert antal kolli"></textarea></label><button class="primary wide">Gem rettelse</button></form>${correctionHistory(item)}`;$('#baggageCorrectionForm').onsubmit=event=>submitCorrection(event,'baggage',item);$('#modal').showModal()}
function showExpenseCorrection(id){const expense=state.trip.expenses.find(item=>item.id===id);if(!expense)return;const trip=state.trip.trip,payers=[state.user,...(state.drivers||[]).filter(driver=>[trip.primaryDriverId,trip.secondaryDriverId].includes(driver.id))].filter((person,index,array)=>array.findIndex(candidate=>candidate.id===person.id)===index);$('#modalBody').innerHTML=`<h2>Ret udgift</h2><p class="muted">En godkendt udgift åbnes automatisk til ny godkendelse, når den rettes.</p><form class="form correction-form" id="expenseCorrectionForm"><label>Kategori<input name="category" value="${esc(expense.category)}" required></label><label>Beløb<input name="amount" type="number" min="0.01" step="0.01" value="${expense.amount}" required></label><label>Valuta<select name="currency"><option value="DKK" ${expense.currency==='DKK'?'selected':''}>DKK</option><option value="EUR" ${expense.currency==='EUR'?'selected':''}>EUR</option></select></label><label>Betalingsmetode<select name="paymentMethod"><option value="company_card" ${expense.paymentMethod==='company_card'?'selected':''}>Firmakort</option><option value="cash" ${expense.paymentMethod==='cash'?'selected':''}>Kontanter</option><option value="private" ${expense.paymentMethod==='private'?'selected':''}>Privat udlæg</option></select></label><label class="wide">Betalt af<select name="paidByUserId">${payers.map(person=>`<option value="${person.id}" ${person.id===expense.paidByUserId?'selected':''}>${esc(person.name)}</option>`).join('')}</select></label><label class="wide">Beskrivelse<textarea name="description">${esc(expense.description||'')}</textarea></label><label class="wide correction-reason">Hvorfor rettes registreringen?<textarea name="correctionReason" minlength="3" required placeholder="F.eks. forkert beløb eller kategori"></textarea></label><button class="primary wide">Gem rettelse</button></form>${correctionHistory(expense)}`;$('#expenseCorrectionForm').onsubmit=event=>submitExpenseCorrection(event,expense);$('#modal').showModal()}
async function submitCorrection(event,part,record){event.preventDefault();try{const payload={id:record.id,edit:true,...Object.fromEntries(new FormData(event.target))};const updated=await api(`/api/trips/${state.trip.trip.id}/${part}`,{method:'PATCH',body:JSON.stringify(payload)});const collection=part==='passengers'?state.trip.passengers:state.trip.baggage;Object.assign(collection.find(item=>item.id===record.id),updated);state.trip.seats=await api(`/api/trips/${state.trip.trip.id}/seats`);$('#modal').close();toast('Rettelsen er gemt i historikken');renderTrip()}catch(error){toast(error.message)}}
async function submitExpenseCorrection(event,expense){event.preventDefault();try{const updated=await api(`/api/expenses/${expense.id}`,{method:'PATCH',body:JSON.stringify({edit:true,...Object.fromEntries(new FormData(event.target))})});Object.assign(expense,updated);$('#modal').close();toast('Udgiften er rettet og historikken er gemt');renderTrip()}catch(error){toast(error.message)}}

const expenseCardBeforeCorrections=expenseCard;
expenseCard=function(expense){return expenseCardBeforeCorrections(expense).replace('<div class="expense-card-actions">',`<div class="expense-card-actions"><button class="mini correction-button" data-edit-expense="${expense.id}">Ret oplysninger</button>`)};
function wireCorrectionButtons(){
  $$('[data-passenger-detail]').forEach(button=>{if(!button.parentElement.querySelector('[data-edit-passenger]'))button.insertAdjacentHTML('beforebegin',`<button class="icon-action correction-button" data-edit-passenger="${button.dataset.passengerDetail}" title="Ret passager">✎</button>`)});
  $$('select[data-bag]').forEach(select=>{const item=state.trip.baggage.find(record=>record.id===Number(select.dataset.bag)),senderCell=select.closest('tr')?.querySelector('td');if(item&&senderCell&&!senderCell.querySelector('.baggage-recipient'))senderCell.insertAdjacentHTML('beforeend',`<span class="baggage-recipient">Modtager: <b>${esc(item.recipientName||'Ikke angivet')}</b></span>`);if(!select.parentElement.querySelector('[data-edit-baggage]'))select.insertAdjacentHTML('afterend',`<button class="mini correction-button" data-edit-baggage="${select.dataset.bag}">Ret</button>`)});
  $$('[data-edit-passenger]').forEach(button=>button.onclick=()=>showPassengerCorrection(Number(button.dataset.editPassenger)));
  $$('[data-edit-baggage]').forEach(button=>button.onclick=()=>showBaggageCorrection(Number(button.dataset.editBaggage)));
  $$('[data-edit-expense]').forEach(button=>button.onclick=()=>showExpenseCorrection(Number(button.dataset.editExpense)));
}
const renderTabBeforeCorrections=renderTab;
renderTab=function(){renderTabBeforeCorrections();wireCorrectionButtons()};
const renderCheckInModeBeforeCorrections=renderCheckInMode;
renderCheckInMode=function(){renderCheckInModeBeforeCorrections();wireCorrectionButtons()};

// Cash transfers between the two drivers require acceptance by the receiver.
function transferStatusLabel(status){return status==='accepted'?'Modtaget':status==='rejected'?'Afvist':'Afventer modtager'}
function transferReferenceLabel(reference){const [kind,rawId]=reference.split(':'),collection=kind==='passenger'?state.trip.passengers:state.trip.baggage,record=collection.find(item=>item.id===Number(rawId));return record?`${kind==='passenger'?'Billet':'Bagage'} · ${record.name||record.senderName}`:reference}
function pendingCashReferences(){const transfers=(state.trip.transfers||[]).filter(item=>item.status==='pending').flatMap(item=>item.paymentRefs),settlements=(state.trip.settlements||[]).filter(item=>item.status==='pending').flatMap(item=>item.paymentRefs||[]);return new Set([...transfers,...settlements])}
function transferableCash(driverId){const locked=pendingCashReferences();return[...state.trip.passengers.map(record=>({record,kind:'passenger'})),...state.trip.baggage.map(record=>({record,kind:'baggage'}))].filter(item=>item.record.cashHolderUserId===driverId&&item.record.paymentLocation==='bus'&&!item.record.cashHandedOverAt&&!locked.has(`${item.kind}:${item.record.id}`))}
function transferHistoryRow(transfer){return`<tr><td><strong>${esc(transfer.fromDriverName)}</strong><br><small>til ${esc(transfer.toDriverName)}</small></td><td>${money(transfer.totals.DKK,'DKK')}<br>${money(transfer.totals.EUR,'EUR')}</td><td>${transfer.paymentRefs.length} betalinger<br><small>${transfer.paymentRefs.map(transferReferenceLabel).map(esc).join(', ')}</small></td><td><span class="cash-transfer-status ${transfer.status}">${transferStatusLabel(transfer.status)}</span></td><td>${date(transfer.respondedAt||transfer.initiatedAt)}</td></tr>`}
function cashTransferPanel(){const trip=state.trip.trip,transfers=state.trip.transfers||[],isDriver=state.user.role==='driver',otherDriverId=isDriver?[trip.primaryDriverId,trip.secondaryDriverId].find(id=>id&&id!==state.user.id):null,eligible=isDriver?transferableCash(state.user.id):[],incoming=transfers.filter(item=>item.status==='pending'&&item.toDriverId===state.user.id),outgoing=transfers.filter(item=>item.status==='pending'&&item.fromDriverId===state.user.id);return`<section class="cash-transfer-panel"><header><div><small>CHAUFFØR TIL CHAUFFØR</small><h2>Overfør kontanter</h2><p>Vælg de konkrete billet- og bagagebetalinger. Modtageren skal bekræfte pengene, før ansvaret flyttes.</p></div><span class="transfer-security">✓ Begge chauffører får kvittering</span></header>${incoming.map(item=>`<div class="incoming-transfer"><div><small>AFVENTER DIN BEKRÆFTELSE</small><strong>${esc(item.fromDriverName)} har overført ${money(item.totals.DKK,'DKK')} · ${money(item.totals.EUR,'EUR')}</strong><span>${item.paymentRefs.length} betalinger${item.note?` · ${esc(item.note)}`:''}</span></div><div><button class="primary" data-accept-transfer="${item.id}">Bekræft modtaget</button><button class="mini danger" data-reject-transfer="${item.id}">Afvis</button></div></div>`).join('')}${outgoing.map(item=>`<div class="outgoing-transfer"><strong>Afventer ${esc(item.toDriverName)}</strong><span>${money(item.totals.DKK,'DKK')} · ${money(item.totals.EUR,'EUR')} · ${item.paymentRefs.length} betalinger</span></div>`).join('')}${isDriver&&otherDriverId?eligible.length?`<form class="cash-transfer-form" id="cashTransferForm"><div class="transfer-recipient"><span>Overfør fra <b>${esc(state.user.name)}</b></span><i>→</i><span>til <b>${esc(tripDriverName(otherDriverId))}</b></span><input type="hidden" name="toDriverId" value="${otherDriverId}"></div><div class="transfer-payment-list">${eligible.map(item=>`<label><input type="checkbox" name="paymentRefs" value="${item.kind}:${item.record.id}"><span><strong>${esc(item.record.name||item.record.senderName)}</strong><small>${item.kind==='passenger'?'Billet':'Bagage'}</small></span><b>${money(item.record.cashAmount,item.record.paymentCurrency||'DKK')}</b></label>`).join('')}</div><label>Bemærkning<textarea name="note" placeholder="Valgfri besked til den anden chauffør"></textarea></label><button class="primary">Send til bekræftelse</button></form>`:'<div class="settlement-empty">Ingen frie betalinger kan overføres lige nu</div>':isDriver?'<div class="settlement-empty">Turen skal have to tildelte chauffører, før kontanter kan overføres.</div>':''}<section class="panel transfer-history"><div class="panel-head"><h3>Overførselshistorik</h3><small>${transfers.length} overførsler</small></div>${transfers.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Fra / til</th><th>Beløb</th><th>Betalinger</th><th>Status</th><th>Tidspunkt</th></tr></thead><tbody>${[...transfers].reverse().map(transferHistoryRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen overførsler mellem chaufførerne endnu</div>'}</section></section>`}
function wireCashTransfers(){
  const form=$('#cashTransferForm');if(form)form.onsubmit=async event=>{event.preventDefault();const paymentRefs=[...form.querySelectorAll('input[name="paymentRefs"]:checked')].map(input=>input.value);if(!paymentRefs.length)return toast('Vælg mindst én betaling');try{await api(`/api/trips/${state.trip.trip.id}/transfers`,{method:'POST',body:JSON.stringify({toDriverId:form.toDriverId.value,paymentRefs,note:form.note.value})});state.trip=await api(`/api/trips/${state.trip.trip.id}`);toast('Overførslen afventer modtagerens bekræftelse');renderTrip()}catch(error){toast(error.message)}};
  $$('[data-accept-transfer]').forEach(button=>button.onclick=()=>respondCashTransfer(Number(button.dataset.acceptTransfer),'accepted'));
  $$('[data-reject-transfer]').forEach(button=>button.onclick=()=>respondCashTransfer(Number(button.dataset.rejectTransfer),'rejected'));
}
async function respondCashTransfer(id,status){if(status==='accepted'&&!confirm('Bekræft, at du fysisk har modtaget de valgte kontanter.'))return;try{await api(`/api/trips/${state.trip.trip.id}/transfers`,{method:'PATCH',body:JSON.stringify({id,status})});state.trip=await api(`/api/trips/${state.trip.trip.id}`);toast(status==='accepted'?'Kontanterne står nu hos dig':'Overførslen er afvist');renderTrip()}catch(error){toast(error.message)}}
const renderSettlementTabBeforeTransfers=renderSettlementTab;
renderSettlementTab=function(){renderSettlementTabBeforeTransfers();const history=$('.settlement-history');if(history){history.insertAdjacentHTML('beforebegin',cashTransferPanel());wireCashTransfers()}};

// Per-trip timetable for arrival and departure at every planned pickup stop.
function timetableRows(){return [...(state.trip?.trip?.timetable||[])].sort((left,right)=>new Date(left.arrivalAt)-new Date(right.arrivalAt))}
function timetableStop(stopId){return timetableRows().find(row=>row.stopId===Number(stopId))}
function timetableClock(value){return value?copenhagenTime(value):'–'}
function timetableDay(value){return value?copenhagenFormat(value,{weekday:'short',day:'2-digit',month:'short'}):'–'}
function localDateTimeValue(value){return copenhagenInputValue(value)}
function timetablePanel(){const rows=timetableRows(),trip=state.trip.trip,completed=trip.completedStopIds||[];return`<section class="trip-timetable"><header><div><small>TURTIDSPLAN · EUROPE/COPENHAGEN</small><h2>Ankomst og afgang</h2><p>${rows.length} ${rows.length===1?'stoppested':'stoppesteder'} i planlagt rækkefølge · dansk tid</p></div>${state.user.role==='admin'&&trip.status!=='cancelled'?'<button class="mini timetable-edit" id="editTimetable">Rediger tidsplan</button>':''}</header><div class="timetable-route">${rows.length?rows.map((row,index)=>{const stop=state.stops.find(item=>item.id===row.stopId),passengers=state.trip.passengers.filter(item=>item.pickupStopId===row.stopId).length;return`<div class="timetable-stop ${completed.includes(row.stopId)?'completed':''}"><i>${completed.includes(row.stopId)?'✓':index+1}</i><div class="timetable-place"><strong>${esc(stop?.name||'Ukendt sted')}</strong><span>${esc(stop?.address||'Adresse ikke angivet')}</span><small>${passengers} ${passengers===1?'passager':'passagerer'} stiger på</small></div><div><span>Ankomst</span><strong>${timetableClock(row.arrivalAt)}</strong><small>${timetableDay(row.arrivalAt)}</small></div><b>→</b><div><span>Afgang</span><strong>${timetableClock(row.departureAt)}</strong><small>${timetableDay(row.departureAt)}</small></div></div>`}).join(''):'<div class="empty">Der er endnu ikke oprettet en tidsplan for turen</div>'}</div></section>`}
function showTimetableDialog(){const trip=state.trip.trip,existing=new Map(timetableRows().map(row=>[row.stopId,row])),base=new Date(trip.departureAt),duration=(Number(trip.durationMinutes)||480)*60000,rank=stop=>stop.id===trip.originId?0:stop.id===trip.destinationId?3:existing.has(stop.id)?1:2,ordered=[...state.stops].sort((left,right)=>rank(left)-rank(right)||(existing.has(left.id)&&existing.has(right.id)?new Date(existing.get(left.id).arrivalAt)-new Date(existing.get(right.id).arrivalAt):left.name.localeCompare(right.name,'da')));$('#modalBody').innerHTML=`<h2>Rediger turens tidsplan</h2><p class="muted">Alle tider indtastes som København-tid (Europe/Copenhagen). Dansk sommer- og vintertid håndteres automatisk.</p><form id="timetableForm" class="timetable-form">${ordered.map((stop,index)=>{const row=existing.get(stop.id),required=[trip.originId,trip.destinationId].includes(stop.id),progress=ordered.length>1?index/(ordered.length-1):0,fallback=new Date(base.getTime()+duration*progress),arrival=row?.arrivalAt||fallback.toISOString(),departure=row?.departureAt||(stop.id===trip.destinationId?fallback.toISOString():new Date(fallback.getTime()+10*60000).toISOString());return`<div class="timetable-form-row" data-timetable-row="${stop.id}"><label class="timetable-include"><input type="checkbox" ${row||required?'checked':''} ${required?'disabled':''}><span><strong>${esc(stop.name)}</strong><small>${required?(stop.id===trip.originId?'Startsted':'Slutsted'):esc(stop.address||'Valgfrit stop')}</small></span></label><label>Ankomst · København<input name="arrivalAt" type="datetime-local" value="${localDateTimeValue(arrival)}" ${row||required?'':'disabled'} required></label><label>Afgang · København<input name="departureAt" type="datetime-local" value="${localDateTimeValue(departure)}" ${row||required?'':'disabled'} required></label></div>`}).join('')}<button class="primary">Gem tidsplan</button></form>`;$$('[data-timetable-row]').forEach(row=>{const checkbox=row.querySelector('input[type="checkbox"]');checkbox.onchange=()=>row.querySelectorAll('input[type="datetime-local"]').forEach(input=>input.disabled=!checkbox.checked)});$('#timetableForm').onsubmit=saveTimetable;$('#modal').showModal()}
async function saveTimetable(event){event.preventDefault();const timetable=$$('[data-timetable-row]').filter(row=>row.querySelector('input[type="checkbox"]').checked).map(row=>({stopId:Number(row.dataset.timetableRow),arrivalAt:copenhagenDateFromInput(row.querySelector('[name="arrivalAt"]').value).toISOString(),departureAt:copenhagenDateFromInput(row.querySelector('[name="departureAt"]').value).toISOString()}));try{const updated=await api(`/api/trips/${state.trip.trip.id}`,{method:'PATCH',body:JSON.stringify({timetable})});state.trip.trip=updated;const overview=state.trips.find(item=>item.id===updated.id);if(overview)Object.assign(overview,updated);$('#modal').close();toast('Turens tidsplan er gemt i København-tid');renderTrip()}catch(error){toast(error.message)}}
const renderTripBeforeTimetable=renderTrip;
renderTrip=function(){renderTripBeforeTimetable();const hero=$('.detail-hero');if(!hero||!state.trip?.trip)return;const lifecycle=$('.trip-lifecycle-actions'),cancelled=$('.trip-cancelled-banner'),anchor=lifecycle||cancelled||hero;anchor.insertAdjacentHTML('afterend',timetablePanel());$('#editTimetable')?.addEventListener('click',showTimetableDialog)};
const renderCheckInBeforeTimetable=renderCheckInMode;
renderCheckInMode=function(){renderCheckInBeforeTimetable();const select=$('#checkinStop');if(!select)return;[...select.options].forEach(option=>{const row=timetableStop(option.value);if(row)option.textContent=`${option.textContent} · ank. ${timetableClock(row.arrivalAt)} · afg. ${timetableClock(row.departureAt)}`});const current=timetableStop(state.currentCheckinStop),host=select.closest('div');if(current&&host&&!host.querySelector('.current-stop-time'))host.insertAdjacentHTML('beforeend',`<div class="current-stop-time"><span><small>ANKOMST</small><strong>${timetableClock(current.arrivalAt)}</strong></span><i>→</i><span><small>AFGANG</small><strong>${timetableClock(current.departureAt)}</strong></span><em>${timetableDay(current.arrivalAt)}</em></div>`)};

// Optional ticket reference. It supports lookup without making the field required in daily work.
const passengerFormBeforeTicketNumber=passengerForm;
passengerForm=function(){return passengerFormBeforeTicketNumber().replace('<label>Telefon<input name="phone" required></label>','<label>Telefon<input name="phone" required></label><label class="optional-ticket-field">Billetnummer <small>valgfrit</small><input name="ticketNumber" maxlength="60" autocomplete="off" placeholder="F.eks. ALBA-1048"></label>')};
const showPassengerCorrectionBeforeTicketNumber=showPassengerCorrection;
showPassengerCorrection=function(id){showPassengerCorrectionBeforeTicketNumber(id);const passenger=state.trip.passengers.find(item=>item.id===id),form=$('#passengerCorrectionForm');if(!passenger||!form)return;const phone=form.elements.phone?.closest('label');phone?.insertAdjacentHTML('afterend',`<label>Billetnummer <small>valgfrit</small><input name="ticketNumber" maxlength="60" value="${esc(passenger.ticketNumber||'')}"></label>`)};
const showPassengerDetailBeforeTicketNumber=showPassengerDetail;
showPassengerDetail=function(id){showPassengerDetailBeforeTicketNumber(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.ticketNumber)return;const phoneRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Telefon');phoneRow?.insertAdjacentHTML('afterend',`<div><span>Billetnummer</span><strong>${esc(passenger.ticketNumber)}</strong></div>`)};
const renderEnhancedPassengerTabBeforeTicketNumber=renderEnhancedPassengerTab;
renderEnhancedPassengerTab=function(){renderEnhancedPassengerTabBeforeTicketNumber();$$('[data-passenger-row]').forEach(row=>{const id=Number(row.querySelector('[data-passenger-detail]')?.dataset.passengerDetail),passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.ticketNumber)return;row.dataset.search=`${row.dataset.search||''} ${passenger.ticketNumber.toLowerCase()}`;const cell=row.cells[0];if(cell&&!cell.querySelector('.ticket-number-note'))cell.insertAdjacentHTML('beforeend',`<span class="ticket-number-note">Billet ${esc(passenger.ticketNumber)}</span>`)})};
const renderCheckInBeforeTicketNumber=renderCheckInMode;
renderCheckInMode=function(){renderCheckInBeforeTicketNumber();$$('[data-checkin-card]').forEach(card=>{const passenger=state.trip.passengers.find(item=>item.id===Number(card.dataset.checkinCard));if(passenger?.ticketNumber)card.dataset.search=`${card.dataset.search||''} ${passenger.ticketNumber.toLowerCase()}`})};

// Mobile action sheet: the passenger name replaces the row of small action icons.
function showPassengerActionSheet(id){const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger)return;const attendance=passenger.checkedIn?'Checket ind':passenger.attendanceStatus==='no_show'?'Udeblevet':'Afventer',paymentStatus=passenger.paymentStatus==='cash'?'Betalt':passenger.paymentStatus==='free'?'Gratis billet':'Ikke betalt',receivedBy=passenger.cashHolderUserName||passenger.paymentRecordedByName;$('#modalBody').innerHTML=`<section class="passenger-action-sheet"><header><small>PASSAGERHANDLINGER</small><h2>${esc(passenger.name)}</h2><div><span>Sæde <b>${passenger.seatNumber}</b></span><span>Opsamling <b>${esc(stopName(passenger.pickupStopId))}</b></span><span class="attendance ${passenger.checkedIn?'checked_in':passenger.attendanceStatus||'pending'}">${attendance}</span><span>Betaling <b>${paymentStatus}</b></span>${receivedBy&&passenger.paymentStatus==='cash'?`<span>Modtaget af <b>${esc(receivedBy)}</b></span>`:''}</div></header><div class="passenger-action-grid">${!passenger.checkedIn&&passenger.attendanceStatus!=='no_show'?`<button data-sheet-action="checkin"><i>✓</i><strong>Check ind</strong><small>Registrer passageren ombord</small></button>`:''}${passenger.paymentStatus==='unpaid'?`<button data-sheet-action="payment"><i>¤</i><strong>Betal billet</strong><small>Registrer kontant betaling</small></button>`:''}<a href="tel:${esc(passenger.phone)}"><i>☎</i><strong>Ring</strong><small>${esc(passenger.phone)}</small></a>${!passenger.checkedIn&&passenger.attendanceStatus!=='no_show'?`<button data-sheet-action="noshow" class="warning"><i>×</i><strong>Udeblevet</strong><small>Passageren mødte ikke op</small></button>`:''}<button data-sheet-action="details"><i>•••</i><strong>Alle detaljer</strong><small>Se billet, betaling og historik</small></button></div></section>`;const run=action=>{$('#modal').close();action()};$('[data-sheet-action="checkin"]')?.addEventListener('click',()=>run(()=>performFastCheckIn(id)));$('[data-sheet-action="payment"]')?.addEventListener('click',()=>run(()=>openPaymentDialog('passenger',id)));$('[data-sheet-action="noshow"]')?.addEventListener('click',()=>run(()=>markNoShow(id)));$('[data-sheet-action="details"]')?.addEventListener('click',()=>run(()=>showPassengerDetail(id)));$('#modal').showModal()}
const renderCheckInBeforePassengerActionSheet=renderCheckInMode;
renderCheckInMode=function(){renderCheckInBeforePassengerActionSheet();$$('[data-passenger-actions]').forEach(button=>button.onclick=()=>showPassengerActionSheet(Number(button.dataset.passengerActions)))};

// Upcoming arrival and departure times on the pickup-stop overview.
function upcomingStopTimes(stopId){
  const now=Date.now();
  return (state.trips||[]).flatMap(trip=>(trip.timetable||[]).filter(row=>Number(row.stopId)===Number(stopId)).map(row=>({trip,row})))
    .filter(item=>item.trip.status!=='cancelled'&&new Date(item.row.departureAt||item.row.arrivalAt).getTime()>=now)
    .sort((left,right)=>new Date(left.row.arrivalAt)-new Date(right.row.arrivalAt));
}
function stopSchedule(stop){
  const times=upcomingStopTimes(stop.id),visible=times.slice(0,4);
  if(!visible.length)return'<div class="stop-no-times"><span>○</span><div><strong>Ingen kommende tider</strong><small>Tider vises her, når stedet tilføjes til en planlagt tur.</small></div></div>';
  return`<div class="stop-time-list">${visible.map(({trip,row})=>{const isStart=Number(row.stopId)===Number(trip.originId),displayDate=isStart?row.departureAt:row.arrivalAt;return`<button type="button" class="stop-time-row ${isStart?'start-time-row':''}" data-stop-trip="${trip.id}"><span class="stop-time-date"><b>${copenhagenFormat(displayDate,{day:'2-digit',month:'short'})}</b><small>${copenhagenFormat(displayDate,{weekday:'short'})}</small></span><span class="stop-time-trip"><strong>${esc(trip.title)}</strong><small>${esc(trip.origin?.name||'–')} → ${esc(trip.destination?.name||'–')}</small></span>${isStart?'<span class="stop-time-start"><small>Startsted</small></span><i></i>':`<span class="stop-time-clock"><small>Ankomst</small><b>${copenhagenTime(row.arrivalAt)}</b></span><i>→</i>`}<span class="stop-time-clock"><small>Afgang</small><b>${copenhagenTime(row.departureAt)}</b></span><em>Åbn tur</em></button>`}).join('')}${times.length>visible.length?`<small class="stop-more-times">+ ${times.length-visible.length} senere ${times.length-visible.length===1?'tid':'tider'}</small>`:''}</div>`;
}
renderStops=function(){
  activate('stops');setTitle('Opsamlingssteder');
  const stops=[...(state.stops||[])].sort((left,right)=>left.name.localeCompare(right.name,'da'));
  $('#view').innerHTML=`<div class="stop-page-layout"><section class="panel stop-overview-panel"><div class="panel-head"><div><h2>Steder og kommende tider</h2><small>Alle tider vises i København-tid · Europe/Copenhagen</small></div><span>${stops.length} steder</span></div><div class="stop-schedule-list">${stops.length?stops.map(stop=>`<article class="stop-schedule-card"><header><div class="stop-pin">⌖</div><div><strong>${esc(stop.name)}</strong><small>${esc(stop.address||'Adresse ikke angivet')}</small></div><div class="stop-actions"><button class="mini" data-edit-stop="${stop.id}">Rediger</button><button class="mini danger" data-delete-stop="${stop.id}">Slet</button></div></header>${stopSchedule(stop)}</article>`).join(''):'<div class="empty">Ingen opsamlingssteder er oprettet</div>'}</div></section><section class="panel stop-create-panel"><div class="panel-head"><div><h2>Tilføj sted</h2><small>Stedets tider planlægges på den enkelte tur</small></div></div><form class="form" id="stopForm"><label>Navn<input name="name" required placeholder="Fx Kolding"></label><label>Adresse<input name="address" placeholder="Adresse eller holdeplads"></label><button class="primary">Tilføj opsamlingssted</button></form></section></div>`;
  $('#stopForm').onsubmit=async event=>{event.preventDefault();try{const stop=await api('/api/stops',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.stops.push(stop);toast('Stedet er oprettet');renderStops()}catch(error){toast(error.message)}};
  $$('[data-stop-trip]').forEach(button=>button.onclick=()=>openTrip(Number(button.dataset.stopTrip)));
  $$('[data-edit-stop]').forEach(button=>button.onclick=async()=>{const stop=state.stops.find(item=>item.id===Number(button.dataset.editStop)),name=prompt('Navn på opsamlingssted',stop.name);if(name===null)return;const address=prompt('Adresse',stop.address);if(address===null)return;try{const updated=await api(`/api/stops/${stop.id}`,{method:'PATCH',body:JSON.stringify({name,address})});Object.assign(stop,updated);toast('Stedet er opdateret');renderStops()}catch(error){toast(error.message)}});
  $$('[data-delete-stop]').forEach(button=>button.onclick=async()=>{const stop=state.stops.find(item=>item.id===Number(button.dataset.deleteStop));if(!confirm(`Vil du slette ${stop.name}?`))return;try{await api(`/api/stops/${stop.id}`,{method:'DELETE'});state.stops=state.stops.filter(item=>item.id!==stop.id);toast('Stedet er slettet');renderStops()}catch(error){toast(error.message)}});
};

// A route's starting point has a departure time only.
timetablePanel=function(){
  const rows=timetableRows(),trip=state.trip.trip,completed=trip.completedStopIds||[];
  return`<section class="trip-timetable"><header><div><small>TURTIDSPLAN · EUROPE/COPENHAGEN</small><h2>Ankomst og afgang</h2><p>${rows.length} ${rows.length===1?'stoppested':'stoppesteder'} i planlagt rækkefølge · dansk tid</p></div>${state.user.role==='admin'&&trip.status!=='cancelled'?'<button class="mini timetable-edit" id="editTimetable">Rediger tidsplan</button>':''}</header><div class="timetable-route">${rows.length?rows.map((row,index)=>{const stop=state.stops.find(item=>item.id===row.stopId),passengers=state.trip.passengers.filter(item=>item.pickupStopId===row.stopId).length,isStart=Number(row.stopId)===Number(trip.originId);return`<div class="timetable-stop ${isStart?'route-start':''} ${completed.includes(row.stopId)?'completed':''}"><i>${completed.includes(row.stopId)?'✓':index+1}</i><div class="timetable-place"><strong>${esc(stop?.name||'Ukendt sted')}</strong><span>${esc(stop?.address||'Adresse ikke angivet')}</span><small>${passengers} ${passengers===1?'passager':'passagerer'} stiger på</small></div>${isStart?'<div class="timetable-start-label"><span>STARTSTED</span><strong>Kun afgang</strong><small>Ingen ankomsttid</small></div><b></b>':`<div><span>Ankomst</span><strong>${timetableClock(row.arrivalAt)}</strong><small>${timetableDay(row.arrivalAt)}</small></div><b>→</b>`}<div><span>Afgang</span><strong>${timetableClock(row.departureAt)}</strong><small>${timetableDay(row.departureAt)}</small></div></div>`}).join(''):'<div class="empty">Der er endnu ikke oprettet en tidsplan for turen</div>'}</div></section>`;
};
const showTimetableDialogBeforeStartRule=showTimetableDialog;
showTimetableDialog=function(){
  showTimetableDialogBeforeStartRule();
  const startRow=$(`[data-timetable-row="${state.trip.trip.originId}"]`),arrival=startRow?.querySelector('[name="arrivalAt"]'),departure=startRow?.querySelector('[name="departureAt"]');
  if(!arrival||!departure)return;
  const label=arrival.closest('label');label.hidden=true;label.insertAdjacentHTML('afterend','<div class="start-departure-note"><strong>Startsted</strong><small>Her registreres kun afgangstid.</small></div>');
  arrival.required=false;
  const form=$('#timetableForm'),submit=form.onsubmit;form.onsubmit=event=>{arrival.value=departure.value;return submit(event)};
};
const renderCheckInBeforeStartTimeRule=renderCheckInMode;
renderCheckInMode=function(){
  renderCheckInBeforeStartTimeRule();
  const trip=state.trip?.trip;if(!trip)return;
  const originOption=[...($('#checkinStop')?.options||[])].find(option=>Number(option.value)===Number(trip.originId));
  if(originOption)originOption.textContent=originOption.textContent.replace(/ · ank\. .*? · afg\. /,' · afg. ');
  if(Number(state.currentCheckinStop)===Number(trip.originId)){$('.current-stop-time')?.replaceChildren();const host=$('.current-stop-time');if(host)host.innerHTML=`<span><small>AFGANG FRA STARTSTEDET</small><strong>${timetableClock(timetableStop(trip.originId)?.departureAt)}</strong></span><em>${timetableDay(timetableStop(trip.originId)?.departureAt)}</em>`}
};

// Full-screen double-decker seat picker modelled on the supplied reference layout.
function pickerSeatButton(seat,pendingSeat){const status=seat.passengerId?'occupied':pendingSeat===seat.number?'selected':'available',premium=seat.surcharge?` · ekstra ${seat.surcharge} kr.`:'';return`<button type="button" class="picture-seat ${status} ${seat.type}" data-picker-seat="${seat.number}" ${seat.passengerId?'disabled':''} aria-label="Sæde ${seat.number}, ${status==='occupied'?'optaget':status==='selected'?'valgt':'ledigt'}${premium}">${seat.number}</button>`}
function pickerSeatPairs(seats,pendingSeat,stairAfter=-1){const pairs=[];for(let index=0;index<seats.length;index+=2){pairs.push(`<div class="picture-seat-pair">${seats.slice(index,index+2).map(seat=>pickerSeatButton(seat,pendingSeat)).join('')}</div>`);if(index/2===stairAfter)pairs.push('<div class="picture-stairs"><span>Trappe</span></div>')}return pairs.join('')}
function pictureUpperDeck(seats,pendingSeat){const rows=[];for(let index=0;index<seats.length;index+=4)rows.push(seats.slice(index,index+4));const left=rows.flatMap(row=>row.slice(0,2)),right=rows.flatMap(row=>row.slice(2,4));return`<section class="picture-deck picture-upper"><header><span class="picture-bus-icon">▣</span><div><strong>Overdæk</strong><small>${seats.length} sæder · ${seats[0]?.number||'–'}–${seats.at(-1)?.number||'–'}</small></div></header><div class="picture-bus-outline"><div class="picture-upper-columns"><div class="picture-seat-column">${pickerSeatPairs(left,pendingSeat,0)}</div><div class="picture-aisle"></div><div class="picture-seat-column">${pickerSeatPairs(right,pendingSeat,9)}</div></div></div></section>`}
function pictureTableGroup(seats,pendingSeat,index){return`<div class="picture-table-group"><div>${seats.slice(0,2).map(seat=>pickerSeatButton(seat,pendingSeat)).join('')}</div><span>BORD ${index}</span><div>${seats.slice(2,4).map(seat=>pickerSeatButton(seat,pendingSeat)).join('')}</div></div>`}
function pictureLowerDeck(seats,pendingSeat){const tableSeats=seats.filter(seat=>seat.type==='table').slice(0,8),regular=seats.filter(seat=>seat.type!=='table');return`<section class="picture-deck picture-lower"><header><span class="picture-bus-icon">▣</span><div><strong>Nederdæk</strong><small>${seats.length} sæder · ${seats[0]?.number||'–'}–${seats.at(-1)?.number||'–'}</small></div></header><div class="picture-bus-outline"><div class="picture-cockpit"><div><span>Chauffør</span><i></i></div><div><span>Guide</span><i></i></div><div class="picture-stairs compact"><span>Trappe</span></div></div><div class="picture-lower-front"><div class="picture-stairs tall"><span>Trappe</span></div><div class="picture-magazine">Magasin</div></div><div class="picture-tables">${pictureTableGroup(tableSeats.slice(0,4),pendingSeat,1)}${pictureTableGroup(tableSeats.slice(4,8),pendingSeat,2)}</div><div class="picture-lower-regular">${referencePickerRows(regular,pendingSeat)}</div><div class="picture-facilities"><span>Toilet</span><span>Køkken</span><span>Køleskab</span><div class="picture-stairs wide"><span>Trappe</span></div><b>Bagagerum</b></div></div></section>`}
function referencePickerRows(seats,pendingSeat){let html='';for(let index=0;index<seats.length;index+=4){const row=seats.slice(index,index+4);html+=`<div class="picture-regular-row"><div>${row.slice(0,2).map(seat=>pickerSeatButton(seat,pendingSeat)).join('')}</div><i></i><div>${row.slice(2,4).map(seat=>pickerSeatButton(seat,pendingSeat)).join('')}</div></div>`}return html}
function pictureTripInfo(){const trip=state.trip.trip,bus=trip.bus||{},passengers=state.trip.passengers.length;return`<section class="picture-info-card picture-trip-card"><h3>Din tur</h3><div><i>□</i><span>Afgang<strong>${copenhagenFormat(trip.departureAt,{day:'2-digit',month:'long',year:'numeric'})} · ${copenhagenTime(trip.departureAt)}</strong></span></div><div><i>⌖</i><span>Fra<strong>${esc(trip.origin?.name||'–')}</strong></span></div><div><i>⌖</i><span>Til<strong>${esc(trip.destination?.name||'–')}</strong></span></div><div><i>▣</i><span>Bus<strong>${esc(bus.name||trip.title)}${bus.registration?` · ${esc(bus.registration)}`:''}</strong></span></div><div><i>♙</i><span>Passagerer<strong>${passengers+1}</strong></span></div></section>`}
function pictureLegend(){return`<section class="picture-info-card picture-legend"><h3>Sædeforklaring</h3><span><i class="available"></i>Ledigt</span><span><i class="occupied"></i>Optaget</span><span><i class="reserved"></i>Ekstra pris</span><span><i class="selected"></i>Valgt</span><span><i class="unavailable"></i>Ikke tilgængelig</span></section>`}
function picturePrices(){const front=state.trip.seats.find(seat=>seat.type==='front')?.surcharge||0,table=state.trip.seats.find(seat=>seat.type==='table')?.surcharge||0;return`<aside class="picture-right"><section class="picture-info-card"><h3>Information</h3><p>Nederdækket har 2 borde med fire pladser ved hvert bord.</p><div class="picture-table-key"><span>BORD</span><b>= Bord (4 pers.)</b></div></section><section class="picture-info-card picture-prices"><h3>Priser</h3><span>Standard sæde<b>0 kr.</b></span><span>Bordplads<b>+${table} kr.</b></span><span>Frontsæde / VIP<b>+${front} kr.</b></span></section></aside>`}
function buildPictureSeatPicker(pendingSeat){const lower=state.trip.seats.filter(seat=>seat.deck==='lower').slice(0,22),upper=state.trip.seats.filter(seat=>seat.deck==='upper').slice(0,62),selected=state.trip.seats.find(seat=>seat.number===pendingSeat);return`<div class="picture-seat-picker"><header class="picture-seat-header"><button type="button" id="pictureSeatBack">← <span>Tilbage</span></button><div><h2>Sædeplan – Dobbeltdækkerbus ${esc(state.trip.trip.bus?.registration||'')}</h2><p>Vælg dit sæde på kortet</p></div><span class="picture-stars">★★★★</span></header><div class="picture-seat-body"><aside class="picture-left">${pictureTripInfo()}${pictureLegend()}<section class="picture-info-card picture-selected"><h3>Valgte sæder</h3><strong>${selected?`Sæde ${selected.number}`:'Ingen sæder valgt'}</strong><small>${selected?`${selected.deck==='upper'?'Overdæk':'Nederdæk'}${selected.surcharge?` · +${selected.surcharge} kr.`:''}`:'Tryk på et grønt sæde'}</small></section><button type="button" class="picture-continue" id="pictureSeatContinue" ${selected?'':'disabled'}>Fortsæt</button></aside><main class="picture-decks">${pictureUpperDeck(upper,pendingSeat)}${pictureLowerDeck(lower,pendingSeat)}</main>${picturePrices()}</div></div>`}
function openPictureSeatPicker(form){let pendingSeat=Number(form.seatNumber.value)||state.selectedSeat||null;const dialog=$('#modal');dialog.classList.add('seat-picker-dialog');const draw=()=>{$('#modalBody').innerHTML=buildPictureSeatPicker(pendingSeat);$$('[data-picker-seat]').forEach(button=>button.onclick=()=>{pendingSeat=Number(button.dataset.pickerSeat);draw()});$('#pictureSeatBack').onclick=close;$('#pictureSeatContinue').onclick=()=>{state.selectedSeat=pendingSeat;form.seatNumber.value=String(pendingSeat);const seat=state.trip.seats.find(item=>item.number===pendingSeat),label=form.querySelector('.seat-picker-launcher strong'),note=form.querySelector('.seat-picker-launcher small');if(label)label.textContent=`Sæde ${pendingSeat} valgt`;if(note)note.textContent=`${seat.deck==='upper'?'Overdæk':'Nederdæk'}${seat.surcharge?` · +${seat.surcharge} kr.`:''}`;close()}};const close=()=>{dialog.close();dialog.classList.remove('seat-picker-dialog')};draw();dialog.showModal()}
const wirePassengerFormBeforePictureSeatPicker=wirePassengerForm;
wirePassengerForm=function(){wirePassengerFormBeforePictureSeatPicker();const form=$('#passengerForm'),isDouble=state.trip?.trip?.bus?.type==='double'||state.trip?.trip?.seatCount===84;if(!form||!isDouble)return;const map=form.querySelector('.double-decker-map');if(!map)return;const host=map.parentElement,selected=state.trip.seats.find(seat=>seat.number===state.selectedSeat);map.outerHTML=`<button type="button" class="seat-picker-launcher" id="openPictureSeatPicker"><span>▣</span><div><strong>${selected?`Sæde ${selected.number} valgt`:'Åbn sædeplan'}</strong><small>${selected?`${selected.deck==='upper'?'Overdæk':'Nederdæk'}${selected.surcharge?` · +${selected.surcharge} kr.`:''}`:'Vælg sæde på dobbeltdækkerens plantegning'}</small></div><i>→</i></button>`;$('#openPictureSeatPicker').onclick=()=>openPictureSeatPicker(form)};

// Payment promises in Denmark or Macedonia remain open until money is received.
const passengerRowBeforePaymentRegions=passengerRow;
passengerRow=function(passenger){let html=passengerRowBeforePaymentRegions(passenger);if(!['pay_dk','pay_mk'].includes(passenger.paymentStatus))return html;const button=`<button class="mini payment-action" data-pay-passenger="${passenger.id}">Registrer betaling</button>`;return html.replace(button,`<span class="payment-status unpaid">${paymentStatusLabel(passenger.paymentStatus)}</span>${button}`)};

const checkinCardBeforePaymentRegions=checkinCard;
checkinCard=function(passenger){let html=checkinCardBeforePaymentRegions(passenger);if(!['pay_dk','pay_mk'].includes(passenger.paymentStatus))return html;html=html.replace('IKKE BETALT',paymentStatusLabel(passenger.paymentStatus).toUpperCase()).replace('Kræver handling',paymentStatusLabel(passenger.paymentStatus));if(!html.includes(`data-pay-passenger="${passenger.id}"`))html=html.replace('<a href="tel:',`<button class="pay-button" data-pay-passenger="${passenger.id}">Registrer betaling</button><a href="tel:`);return html};

const renderCheckInBeforePaymentRegions=renderCheckInMode;
renderCheckInMode=function(){renderCheckInBeforePaymentRegions();const atStop=(state.trip?.passengers||[]).filter(passenger=>passenger.pickupStopId===Number(state.currentCheckinStop)),warning=$('.checkin-alerts .warning strong');if(warning)warning.textContent=atStop.filter(isPendingPayment).length;$$('#problemPanel [data-focus-passenger]').forEach(button=>{const passenger=state.trip.passengers.find(item=>item.id===Number(button.dataset.focusPassenger));if(['pay_dk','pay_mk'].includes(passenger?.paymentStatus))button.querySelector('span').textContent=paymentStatusLabel(passenger.paymentStatus)})};

const showPassengerDetailBeforePaymentRegions=showPassengerDetail;
showPassengerDetail=function(id){showPassengerDetailBeforePaymentRegions(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!['pay_dk','pay_mk'].includes(passenger?.paymentStatus))return;const paymentRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Betaling'),holderRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Pengene står hos');if(paymentRow)paymentRow.querySelector('strong').textContent=paymentStatusLabel(passenger.paymentStatus);if(holderRow)holderRow.querySelector('strong').textContent='Ikke modtaget endnu'};

const showPassengerActionSheetBeforePaymentRegions=showPassengerActionSheet;
showPassengerActionSheet=function(id){showPassengerActionSheetBeforePaymentRegions(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!['pay_dk','pay_mk'].includes(passenger?.paymentStatus))return;const payment=[...$$('.passenger-action-sheet header span')].find(span=>span.textContent.trim().startsWith('Betaling'));if(payment)payment.querySelector('b').textContent=paymentStatusLabel(passenger.paymentStatus);const grid=$('.passenger-action-grid');if(grid&&!grid.querySelector('[data-sheet-action="payment"]')){grid.insertAdjacentHTML('afterbegin','<button data-sheet-action="payment"><i>¤</i><strong>Betal billet</strong><small>Registrer kontant betaling</small></button>');grid.querySelector('[data-sheet-action="payment"]').onclick=()=>{$('#modal').close();openPaymentDialog('passenger',id)}}};

const renderReportsBeforePaymentRegions=renderReports;
renderReports=async function(){await renderReportsBeforePaymentRegions();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports');for(const [heading,records] of [['Solgte billetter',report.tickets],['Bagagesalg',report.baggage]]){const panel=[...$$('.report-section')].find(section=>section.querySelector('h2')?.textContent===heading);[...(panel?.querySelectorAll('tbody tr')||[])].forEach((row,index)=>{const record=records[index];if(!record||!row.cells[4]||!['pay_dk','pay_mk'].includes(record.paymentStatus))return;row.cells[4].innerHTML=`<span class="payment-status unpaid">${paymentStatusLabel(record.paymentStatus)}</span>`})}}catch(error){toast(error.message)}};

// Only administrators manage the app logo and driver portrait photos.
const brandingNav=document.createElement('button');brandingNav.className='nav admin-only';brandingNav.dataset.view='branding';brandingNav.innerHTML='◈ <span>Logo & billeder</span>';brandingNav.hidden=true;reportNav.after(brandingNav);brandingNav.onclick=renderBranding;

function refreshBrandLogo(){const source=`/api/branding/logo?v=${Date.now()}`;$$('.brand-logo').forEach(image=>{image.onload=()=>{image.hidden=false;image.closest('.brand')?.classList.add('has-logo')};image.onerror=()=>{image.hidden=true;image.closest('.brand')?.classList.remove('has-logo')};image.src=source})}
function validateProfileImage(file){if(!file)return null;if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Billedet skal være JPG, PNG eller WebP');if(file.size>10*1024*1024)throw Error('Billedet må højst fylde 10 MB');return file}
async function addImageToPayload(payload,file,prefix){if(!file)return payload;validateProfileImage(file);payload[`${prefix}Name`]=file.name;payload[`${prefix}Type`]=file.type;payload[`${prefix}Data`]=await fileAsDataUrl(file);return payload}
function portraitMarkup(driver,className='driver-portrait'){return driver.hasPortrait?`<img class="${className}" src="/api/drivers/${driver.id}/portrait?v=${Date.now()}" alt="Portræt af ${esc(driver.name)}">`:`<span class="${className} fallback">${esc(driver.name.split(' ').map(part=>part[0]).slice(0,2).join(''))}</span>`}
function wireImagePreview(input,preview){input.onchange=()=>{const file=input.files[0];if(!file)return;try{validateProfileImage(file);preview.src=URL.createObjectURL(file);preview.hidden=false}catch(error){input.value='';toast(error.message)}}}

function renderBranding(){if(state.user.role!=='admin')return renderDashboard();activate('branding');setTitle('Logo & billeder','ADMINISTRATOR');const hasLogo=Boolean(state.branding?.hasLogo);$('#view').innerHTML=`<div class="branding-page"><section class="panel"><div class="panel-head"><div><h2>Appens logo</h2><small>Kun administratoren kan ændre logoet</small></div></div><form class="form" id="brandingForm" style="padding:22px"><div class="branding-upload wide"><div class="branding-preview">${hasLogo?'<img id="brandingPreview" src="/api/branding/logo" alt="Nuværende logo">':'<img id="brandingPreview" hidden alt="Forhåndsvisning">'}<div><strong>${hasLogo?'Nuværende logo':'Intet logo uploadet'}</strong><p class="muted">Logoet vises på login og i menuen.</p></div></div><label>Vælg nyt logo<input name="logo" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG eller WebP · maks. 10 MB</small></label></div><button class="primary wide">Gem app-logo</button></form></section><aside class="branding-example">${hasLogo?'<img src="/api/branding/logo" alt="App-logo">':'<div class="driver-portrait fallback">AT</div>'}<h2>Alba Turist BusOps</h2><p>Logoet bliver synligt for administrator, chauffører og salgschefer.</p></aside></div>`;const form=$('#brandingForm'),preview=$('#brandingPreview');wireImagePreview(form.logo,preview);form.onsubmit=async event=>{event.preventDefault();try{const file=validateProfileImage(form.logo.files[0]),payload={};await addImageToPayload(payload,file,'logo');state.branding=await api('/api/branding',{method:'PATCH',body:JSON.stringify(payload)});refreshBrandLogo();toast('App-logoet er gemt');renderBranding()}catch(error){toast(error.message)}}}

renderDrivers=function(){activate('drivers');setTitle('Chauffører');$('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Chauffører i systemet</h2><small>${state.drivers.length} chauffører</small></div>${state.drivers.length?state.drivers.map(driver=>`<div class="stop-card"><div class="driver-profile">${portraitMarkup(driver)}<div><strong>${esc(driver.name)}</strong><div class="muted">${esc(driver.email)}</div></div></div><div class="stop-actions"><button class="mini" data-edit-driver="${driver.id}">Rediger</button><button class="mini danger" data-delete-driver="${driver.id}">Slet</button></div></div>`).join(''):'<div class="empty">Ingen chauffører er oprettet</div>'}</section><section class="panel"><div class="panel-head"><div><h2>Tilføj chauffør</h2><small>Portrættet kan tilføjes nu eller senere</small></div></div><form class="form" id="driverForm" style="padding:22px;display:grid"><div class="portrait-upload wide"><div class="portrait-preview"><img id="newDriverPortraitPreview" hidden alt="Portrætvisning"><div><strong>Portrætfoto</strong><p class="muted">Brug gerne et tydeligt, lodret billede af ansigtet.</p></div></div><label>Vælg billede<input name="portrait" type="file" accept="image/jpeg,image/png,image/webp" capture="user"><small>JPG, PNG eller WebP · maks. 10 MB</small></label></div><label>Fulde navn<input name="name" required placeholder="Chaufførens navn"></label><label>E-mail<input name="email" type="email" required placeholder="navn@albaturist.dk"></label><label>Midlertidig adgangskode<input name="password" type="password" minlength="12" required autocomplete="new-password"><small>Mindst 12 tegn</small></label><button class="primary">Opret chauffør</button></form></section></div>`;const form=$('#driverForm');wireImagePreview(form.portrait,$('#newDriverPortraitPreview'));form.onsubmit=async event=>{event.preventDefault();try{const payload=Object.fromEntries(new FormData(form));const file=form.portrait.files[0];delete payload.portrait;await addImageToPayload(payload,file,'portrait');const driver=await api('/api/drivers',{method:'POST',body:JSON.stringify(payload)});state.drivers.push(driver);toast('Chaufføren er oprettet');renderDrivers()}catch(error){toast(error.message)}};$$('[data-edit-driver]').forEach(button=>button.onclick=()=>openDriverEditor(Number(button.dataset.editDriver)));$$('[data-delete-driver]').forEach(button=>button.onclick=async()=>{const driver=state.drivers.find(item=>item.id===Number(button.dataset.deleteDriver));if(!confirm(`Vil du slette chaufføren ${driver.name}?`))return;try{await api(`/api/drivers/${driver.id}`,{method:'DELETE'});state.drivers=state.drivers.filter(item=>item.id!==driver.id);toast('Chaufføren er slettet');renderDrivers()}catch(error){toast(error.message)}})};

openDriverEditor=function(id){const driver=state.drivers.find(item=>item.id===id);$('#modalBody').innerHTML=`<h2>Rediger chauffør</h2><p class="muted">Administrator kan opdatere oplysninger og portrætfoto.</p><form class="form" id="editDriverForm"><div class="portrait-upload wide"><div class="portrait-preview">${driver.hasPortrait?`<img id="editDriverPortraitPreview" src="/api/drivers/${driver.id}/portrait" alt="Nuværende portræt">`:'<img id="editDriverPortraitPreview" hidden alt="Portrætvisning">'}<div><strong>Portrætfoto</strong><p class="muted">Vælg kun et nyt billede, hvis portrættet skal udskiftes.</p></div></div><label>Nyt portrætfoto<input name="portrait" type="file" accept="image/jpeg,image/png,image/webp" capture="user"><small>Valgfrit · maks. 10 MB</small></label></div><label class="wide">Fulde navn<input name="name" value="${esc(driver.name)}" required></label><label class="wide">E-mail<input name="email" type="email" value="${esc(driver.email)}" required></label><label class="wide">Ny adgangskode<input name="password" type="password" minlength="12" autocomplete="new-password" placeholder="Lad feltet være tomt for at beholde den nuværende"><small>Valgfrit · mindst 12 tegn</small></label><button class="primary wide">Gem ændringer</button></form>`;const form=$('#editDriverForm');wireImagePreview(form.portrait,$('#editDriverPortraitPreview'));form.onsubmit=async event=>{event.preventDefault();try{const payload=Object.fromEntries(new FormData(form)),file=form.portrait.files[0];delete payload.portrait;await addImageToPayload(payload,file,'portrait');const updated=await api(`/api/drivers/${driver.id}`,{method:'PATCH',body:JSON.stringify(payload)});Object.assign(driver,updated);state.trips.forEach(trip=>{if(trip.primaryDriverId===driver.id)trip.primaryDriver=driver.name;if(trip.secondaryDriverId===driver.id)trip.secondaryDriver=driver.name});$('#modal').close();toast('Chaufføren er opdateret');renderDrivers()}catch(error){toast(error.message)}};$('#modal').showModal()};

const roleUiBeforeBranding=roleUi;roleUi=function(){roleUiBeforeBranding();brandingNav.hidden=state.user.role!=='admin';if(state.user.hasPortrait){$('#avatar').innerHTML=`<img src="/api/drivers/${state.user.id}/portrait" alt="${esc(state.user.name)}">`}refreshBrandLogo()};
refreshBrandLogo();

const accountNav=document.createElement('button');accountNav.className='nav';accountNav.dataset.view='account';accountNav.innerHTML='⚙ <span>Min konto</span>';brandingNav.after(accountNav);accountNav.onclick=renderAccount;

function accountRoleLabel(){return state.user.role==='admin'?'Administrator':state.user.role==='sales_manager'?'Salgschef':'Chauffør'}
function renderAccount(){activate('account');setTitle('Min konto','PERSONLIGE INDSTILLINGER');const user=state.user;$('#view').innerHTML=`<div class="account-page"><section class="panel account-profile-card"><div class="account-profile-identity">${user.role==='driver'&&user.hasPortrait?`<img src="/api/drivers/${user.id}/portrait" alt="Portræt af ${esc(user.name)}">`:`<span>${esc(user.name.split(' ').map(part=>part[0]).slice(0,2).join(''))}</span>`}<div><small>${accountRoleLabel().toUpperCase()}</small><h2>${esc(user.name)}</h2><p>${esc(user.email)}</p></div></div><div class="account-security-note"><b>🔒</b><div><strong>Dine loginoplysninger er personlige</strong><p>Kun du kan ændre din e-mail og adgangskode. Administratoren kan ikke se din adgangskode.</p></div></div></section><section class="panel"><div class="panel-head"><div><h2>Login og sikkerhed</h2><small>Bekræft altid med din nuværende adgangskode</small></div></div><form class="form account-form" id="accountForm"><label class="wide">E-mail<input name="email" type="email" autocomplete="email" value="${esc(user.email)}" required></label><label class="wide">Nuværende adgangskode<input name="currentPassword" type="password" autocomplete="current-password" required><small>Kræves for at gemme ændringer</small></label><label>Ny adgangskode<input name="newPassword" type="password" minlength="12" autocomplete="new-password" placeholder="Lad feltet være tomt, hvis den ikke ændres"></label><label>Gentag ny adgangskode<input name="confirmPassword" type="password" minlength="12" autocomplete="new-password"></label><div class="password-guidance wide"><strong>En sikker adgangskode skal have mindst 12 tegn.</strong><span>Når adgangskoden ændres, logges dine andre enheder automatisk ud.</span></div><button class="primary wide">Gem mine loginoplysninger</button></form></section></div>`;const form=$('#accountForm');form.onsubmit=async event=>{event.preventDefault();if(form.newPassword.value!==form.confirmPassword.value)return toast('De to nye adgangskoder er ikke ens');try{const response=await api('/api/profile',{method:'PATCH',body:JSON.stringify({email:form.email.value,currentPassword:form.currentPassword.value,newPassword:form.newPassword.value})});state.user=response.user;roleUi();toast('Dine loginoplysninger er opdateret');renderAccount()}catch(error){toast(error.message)}}}

editSalesManager=function(id){const manager=state.salesManagers.find(item=>item.id===id);$('#modalBody').innerHTML=`<h2>Rediger salgschef</h2><p class="muted">Administrator kan ændre navnet. Salgschefen ændrer selv e-mail og adgangskode under Min konto.</p><form class="form" id="editSalesManagerForm"><label class="wide">Fulde navn<input name="name" value="${esc(manager.name)}" required></label><div class="personal-login-lock wide"><b>🔒</b><span><strong>${esc(manager.email)}</strong><small>Personlige loginoplysninger administreres af salgschefen selv</small></span></div><button class="primary wide">Gem navn</button></form>`;$('#editSalesManagerForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/sales-managers/${manager.id}`,{method:'PATCH',body:JSON.stringify({name:event.target.name.value})});Object.assign(manager,updated);state.trips.forEach(trip=>{if(trip.salesManagerId===manager.id)trip.salesManager=manager.name});$('#modal').close();toast('Salgschefen er opdateret');renderSalesManagers()}catch(error){toast(error.message)}};$('#modal').showModal()};

openDriverEditor=function(id){const driver=state.drivers.find(item=>item.id===id);$('#modalBody').innerHTML=`<h2>Rediger chauffør</h2><p class="muted">Administrator kan ændre navn og portræt. Chaufføren ændrer selv sine loginoplysninger.</p><form class="form" id="editDriverForm"><div class="portrait-upload wide"><div class="portrait-preview">${driver.hasPortrait?`<img id="editDriverPortraitPreview" src="/api/drivers/${driver.id}/portrait" alt="Nuværende portræt">`:'<img id="editDriverPortraitPreview" hidden alt="Portrætvisning">'}<div><strong>Portrætfoto</strong><p class="muted">Vælg kun et nyt billede, hvis portrættet skal udskiftes.</p></div></div><label>Nyt portrætfoto<input name="portrait" type="file" accept="image/jpeg,image/png,image/webp" capture="user"><small>Valgfrit · maks. 10 MB</small></label></div><label class="wide">Fulde navn<input name="name" value="${esc(driver.name)}" required></label><div class="personal-login-lock wide"><b>🔒</b><span><strong>${esc(driver.email)}</strong><small>Chaufføren ændrer selv e-mail og adgangskode under Min konto</small></span></div><button class="primary wide">Gem chaufføren</button></form>`;const form=$('#editDriverForm');wireImagePreview(form.portrait,$('#editDriverPortraitPreview'));form.onsubmit=async event=>{event.preventDefault();try{const payload={name:form.name.value},file=form.portrait.files[0];await addImageToPayload(payload,file,'portrait');const updated=await api(`/api/drivers/${driver.id}`,{method:'PATCH',body:JSON.stringify(payload)});Object.assign(driver,updated);state.trips.forEach(trip=>{if(trip.primaryDriverId===driver.id)trip.primaryDriver=driver.name;if(trip.secondaryDriverId===driver.id)trip.secondaryDriver=driver.name});$('#modal').close();toast('Chaufføren er opdateret');renderDrivers()}catch(error){toast(error.message)}};$('#modal').showModal()};

