let currentAppLanguage='da';
function translatedText(value){const entry=translationTable[String(value).trim()];return currentAppLanguage==='da'||!entry?null:entry[currentAppLanguage]}
function translateElement(root=document.body){if(!root||currentAppLanguage==='da')return;const nodes=[];if(root.nodeType===Node.TEXT_NODE)nodes.push(root);else{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode)}for(const node of nodes){const original=node.nodeValue,trimmed=original.trim(),translated=translatedText(trimmed);if(translated)node.nodeValue=original.replace(trimmed,translated)}for(const element of root.querySelectorAll?.('[placeholder],[title],[aria-label]')||[]){for(const attribute of ['placeholder','title','aria-label']){const value=element.getAttribute(attribute),translated=value&&translatedText(value);if(translated)element.setAttribute(attribute,translated)}}}
function setAppLanguage(language){currentAppLanguage=['da','sq','de','en'].includes(language)?language:'da';document.documentElement.lang=currentAppLanguage;try{localStorage.setItem('busopsLanguage',currentAppLanguage)}catch(_){};translateElement(document.body)}
const languageObserver=new MutationObserver(records=>{if(currentAppLanguage==='da')return;for(const record of records)for(const node of record.addedNodes)translateElement(node)});languageObserver.observe(document.documentElement,{childList:true,subtree:true});

const renderAccountBeforeLanguage=renderAccount;
renderAccount=function(){renderAccountBeforeLanguage();const identity=$('.account-profile-identity');if(!identity)return;identity.insertAdjacentHTML('afterend',`<div class="account-language"><div><small>SPROG / LANGUAGE</small><strong>${translatedText('Vælg appens sprog')||'Vælg appens sprog'}</strong><span>${translatedText('Sproget gemmes på din brugerprofil')||'Sproget gemmes på din brugerprofil'}</span></div><select id="accountLanguage" aria-label="Sprog">${Object.entries(languageNames).map(([code,name])=>`<option value="${code}" ${code===(state.user.language||'da')?'selected':''}>${name}</option>`).join('')}</select></div>`);$('#accountLanguage').onchange=async event=>{try{const response=await api('/api/profile/language',{method:'PATCH',body:JSON.stringify({language:event.target.value})});state.user.language=response.language;try{localStorage.setItem('busopsLanguage',response.language)}catch(_){};location.reload()}catch(error){toast(error.message)}};translateElement($('#view'))};
accountNav.onclick=()=>renderAccount();

function keepActiveControlVisible(selector){if(!window.matchMedia('(max-width: 700px)').matches)return;requestAnimationFrame(()=>document.querySelector(selector)?.scrollIntoView({block:'nearest',inline:'center'}))}
const activateBeforeResponsiveAudit=activate;
activate=function(name){activateBeforeResponsiveAudit(name);keepActiveControlVisible(`.sidebar .nav[data-view="${name}"]`)};
const renderTripBeforeResponsiveAudit=renderTrip;
renderTrip=function(){renderTripBeforeResponsiveAudit();keepActiveControlVisible('.tabs .tab.active')};

async function performManualUncheck(id){const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.checkedIn)return toast('Passageren er ikke checket ind');try{if(!navigator.onLine)throw Error('offline');const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,checkedIn:false})});Object.assign(passenger,updated,{pendingSync:false})}catch(error){const offline=!navigator.onLine||/fetch|network|offline|load failed/i.test(error.message);if(!offline)return toast(error.message);const pendingLocal=passenger.pendingSync&&offlineQueue().some(item=>item.id===id&&item.checkedIn===true);removeOfflineCheckIn(id);if(!pendingLocal)queueOfflineCheckIn({tripId:state.trip.trip.id,id,checkedIn:false});Object.assign(passenger,{checkedIn:false,attendanceStatus:'pending',checkedInAt:null,checkedInBy:null,checkedInByName:null,pendingSync:!pendingLocal})}if(state.lastCheckIn?.id===id)state.lastCheckIn=null;state.currentCheckinStop=passenger.pickupStopId;state.checkInListFilter='pending';toast('Check-in er fjernet · passageren står under Afventer');renderTrip()}
const showPassengerActionSheetBeforeManualUncheck=showPassengerActionSheet;
showPassengerActionSheet=function(id){showPassengerActionSheetBeforeManualUncheck(id);const passenger=state.trip.passengers.find(item=>item.id===id),grid=$('.passenger-action-grid');if(!passenger?.checkedIn||!grid)return;grid.insertAdjacentHTML('afterbegin','<button data-sheet-action="uncheck" class="warning"><i>↶</i><strong>Fjern check-in</strong><small>Flyt passageren tilbage til afventer</small></button>');grid.querySelector('[data-sheet-action="uncheck"]').onclick=()=>{$('#modal').close();performManualUncheck(id)}};

try{setAppLanguage(localStorage.getItem('busopsLanguage')||'da')}catch(_){setAppLanguage('da')}
